#include "FiveWin.ch"

function Main()
   local oT := TTransformerTL():New( 1, 16, 2, 10 )
   local aBatch := { { 1, 2, 3 }, { 4, 5, 6 }, { 7, 8, 9 } }
   local aTgts  := { { 2, 3, 4 }, { 5, 6, 7 }, { 8, 9, 10 } }
   local nStep, b

   for nStep := 1 to 100
      oT:oTL:ZeroGrad()                             // una vez por batch
      for b := 1 to Len( aBatch )
         // acumula gradientes de parametros; los de activaciones se limpian
         oT:AccumStep( aBatch[ b ], aTgts[ b ], 1 / Len( aBatch ) )
      next
      oT:oTL:ClipGrads( 1.0 )                       // clipping L2 global
      oT:oTL:StepAdam( 0.003 )                      // un paso Adam por batch
   next
return nil

