   // fwtensor.c carga libopenblas.dll dinamicamente (nunca es obligatoria):
   // 1) variable de entorno FWT_BLAS_DLL (o "off" para desactivar)
   // 2) libopenblas.dll junto al exe o en el PATH
   if FWT_BlasActive()
      ? "OpenBLAS activo: einsum/matmul corren sobre cblas_sgemm"
   else
      ? "sin BLAS: bucles C portables"
   endif
return nil

