HB_FUNC( ABRWPOSRECT ) // ( hWnd, nRow, aSizes, nFirstItem, nCol, hFont )
#else
   HB_FUNC( ABRWPOSREC ) // ( hWnd, nRow, aSizes, nFirstItem, nCol, hFont )
#endif
{
	 #ifdef _WIN64
      HWND hWnd   = ( HWND ) hb_parnll( 1 );
      HFONT hFont = ( HFONT ) hb_parnll( 6 );
   #else   
      HWND hWnd   = ( HWND ) hb_parnl( 1 );
      HFONT hFont = ( HFONT ) hb_parnl( 6 );
   #endif

   HDC hDC          = GetDC( hWnd );
   WORD wRow        = ( WORD ) hb_parni( 2 );
   TEXTMETRIC tm;
   RECT rct;
   #ifdef __CLIPPER__
      PCLIPVAR paSizes = hb_param( 3, 0x8000 );
      WORD wLen        = _VARRAYLEN( paSizes );
   #else
      #ifdef __HARBOUR__
         // void * paSizes = ( void * ) hb_param( 3, HB_IT_ARRAY );
         WORD wLen      = ( WORD ) hb_parinfa( 3, 0 );
      #else
         void * paSizes = ( void * ) hb_param( 3, 0x8000 );
         WORD wLen      = _VARRAYLEN( paSizes );
      #endif
   #endif
   WORD wIndex      = ( WORD ) hb_parni( 4 );
   WORD wCol        = ( WORD ) hb_parni( 5 );
   WORD wMaxRight;
   HFONT hOldFont = 0;
   LONG l;

   if( ! wCol || wCol > wLen )
        return;

   if( hFont )
      hOldFont = ( HFONT ) SelectObject( hDC, hFont );

   GetWindowRect( hWnd, &rct );
   wMaxRight = ( WORD ) rct.right;

   GetTextMetrics( hDC, &tm );
   tm.tmHeight += 1;

   rct.top    = rct.top + tm.tmHeight * wRow;
   rct.bottom = rct.top + tm.tmHeight;
   rct.right  = rct.left;

   while( wIndex <= wCol )
   {
        rct.left   = rct.right;

        #ifndef __FLAT__
           rct.right  = ( wIndex == wLen ? wMaxRight
                                         : rct.left + GetInt( paSizes, wIndex ) );
        #else
           #ifndef __HARBOUR__
              #define hb_parnl(x,y) PARNL(x,params,y);
           #endif
           l = hb_parvnl( 3, wIndex );
           rct.right  = ( wIndex == wLen ? wMaxRight
                                         : rct.left + l );
           #undef hb_parnl
        #endif

        if( rct.right >= wMaxRight )
        {
            wIndex = wCol + 1;   // ya no pintamos m s
            rct.right = wMaxRight;
        }
        else
            wIndex++;
   }


   if( hFont )
      SelectObject( hDC, hOldFont );

   ReleaseDC( hWnd, hDC );

   hb_reta( 4 );

   #ifdef __XPP__
      #define hb_storni( x, y, z ) STORNI( x, params, y, z )
   #endif
   hb_storvni( rct.top,    -1, 1 );
   hb_storvni( rct.left,   -1, 2 );
   hb_storvni( rct.bottom, -1, 3 );
   hb_storvni( ( wMaxRight <= rct.right ) ? wMaxRight - 18: rct.right, -1, 4 );
}
