HB_FUNC( EXPONENT )
{
#ifdef CT_EXPONENT_MANTISSA_BIT

   int iExponent = 0;

   union
   {
      double value;
      char string[ sizeof( double ) ];
   } xConvert;

   xConvert.value = hb_parnd( 1 );

   if( xConvert.value != 0 )
   {
      iExponent = ( int ) ( xConvert.string[ 7 ] & 0x07F );
      iExponent = iExponent << 4;
      iExponent += ( int ) ( ( xConvert.string[ 6 ] & 0xF0 ) >> 4 );
      iExponent -= 1023;
   }

   hb_retni( iExponent );

#else

   int iExponent = 0;
   double dValue;

   dValue = hb_parnd( 1 );

   if( dValue == 0.0 )
   {
      hb_retni( 0 );
      return;
   }

   if( fabs( dValue ) < 1.0 )
   {
      while( fabs( dValue ) < 1.0 )
      {
         dValue *= 2.0;
         iExponent--;
      }
   }
   else if( fabs( dValue ) >= 2.0 )
   {
      while( fabs( dValue ) >= 2.0 )
      {
         dValue /= 2.0;
         iExponent++;
      }
   }
   hb_retni( iExponent );

#endif
}
#pragma ENDDUMP

