HB_FUNC( MSGPAINT )
{
    #ifdef _WIN64
      HWND  hWnd    = ( HWND ) hb_parnll( 1 );
      HFONT hFont   = ( HFONT ) hb_parnll( 9 );
      HDC   hDC     = ( HDC ) hb_parnll( 11 );
   #else
      HWND  hWnd         = ( HWND ) hb_parnl( 1 );
      HFONT hFont   = ( HFONT ) hb_parnl( 9 );
      HDC   hDC     = ( HDC ) hb_parnl( 11 );
   #endif
   LPSTR cMsg         = ( LPSTR ) hb_parc( 2 );
   LPSTR cMsgDef      = ( LPSTR ) hb_parc( 3 );
   BOOL  bErase       = hb_parl( 4 );
   BOOL  bCenter      = hb_parl( 5 );
   int   nSize        = hb_parni( 6 );
   COLORREF nClrFore  = ( hb_pcount() > 6 ? hb_parnl( 7 ) : 0 );
   COLORREF nClrBack  = ( hb_pcount() > 7 ? hb_parnl( 8 ) : GetSysColor( COLOR_BTNFACE ) );
   BOOL bInset   = hb_parl( 10 );
   HFONT hOldFont = 0;
   RECT  rc;
   WORD  wLen, wRight;
   COLORREF cTextOld, cBkOld;

   GetClientRect( hWnd, &rc );
   wRight = ( WORD ) rc.right;

   rc.top    += 4;
   rc.left   += 4;
   rc.bottom -= 4;
   rc.right  -= 4;

   if( nSize )
      rc.right = nSize - 11;

   if( ( wLen = ( WORD ) hb_parclen( 2 ) ) == 0 )
   {
      wLen = ( WORD ) hb_parclen( 3 );
      cMsg = cMsgDef;
   }

   if( hFont )
      hOldFont = ( HFONT ) SelectObject( hDC, hFont );

   cTextOld = SetTextColor( hDC, nClrFore );
   cBkOld = SetBkColor( hDC, nClrBack );

   ExtTextOut( hDC, 8, 5, ETO_OPAQUE | ETO_CLIPPED, &rc, "", 0, 0 );
   DrawTextAW( hDC, cMsg, wLen, &rc, DT_NOPREFIX | ( bCenter ? DT_CENTER : DT_LEFT ) | DT_VCENTER | DT_SINGLELINE );

   SetTextColor( hDC, cTextOld );
   SetBkColor( hDC, cBkOld );

   if( hFont )
      SelectObject( hDC, hOldFont );

   if( bErase )
   {
      rc.top    -= 4;
      rc.bottom += 3;
      rc.left   -= 4;
      rc.right  = wRight - 1;
      WindowRaised( hDC, &rc );

      if( bInset )
      {
         rc.top    += 3;
         rc.left   += 3;
         rc.right  = ( nSize ? nSize - 9 : wRight - 4 );
         rc.bottom -= 3;
         WindowBoxIn( hDC, &rc );
      }
   }
}
