HB_FUNC( SAYMOVEIN )
{
   HB_SIZE nLen;
   void * hText;
   const HB_WCHAR * pwText = hb_parstr_u16( 1, HB_CDP_ENDIAN_NATIVE, &hText, &nLen );

   if( nLen )
   {
      int iRow, iCol, iMaxRow, iMaxCol;
      long lDelay;
      HB_BOOL fBack;

      lDelay = hb_parnldef( 2, 4 );
      fBack = hb_parl( 5 );

      iMaxRow = hb_gtMaxRow();
      iMaxCol = hb_gtMaxCol();
      hb_gtGetPos( &iRow, &iCol );
      if( HB_ISNUM( 3 ) )
         iRow = hb_parni( 3 );
      if( HB_ISNUM( 4 ) )
         iCol = hb_parni( 4 );

      if( iRow >= 0 && iCol >= 0 && iRow <= iMaxRow && iCol <= iMaxCol )
      {
         HB_SIZE nChars;
         int iColor = hb_gtGetCurrColor();
         int iNewCol;

         iNewCol = iCol + ( int ) nLen;
         if( fBack )
            iCol += ( int ) nLen - 1;
         else
            pwText += ( int ) nLen - 1;
         nChars = 1;

         hb_gtBeginWrite();
         do
         {
            HB_SIZE nPos;

            if( fBack )
            {
               if( iCol <= iMaxCol )
               {
                  for( nPos = 0; nPos < nChars; ++nPos )
                     hb_gtPutChar( iRow, iCol + ( int ) nPos, iColor, 0, pwText[ nPos ] );
               }
               --iCol;
            }
            else
            {
               for( nPos = 0; nPos < nChars; ++nPos )
                  hb_gtPutChar( iRow, iCol + ( int ) nPos, iColor, 0, pwText[ nPos ] );
               --pwText;
            }
            if( ( int ) nChars + iCol <= iMaxCol )
               ++nChars;

            if( lDelay )
            {
               hb_gtEndWrite();
               hb_idleSleep( ( double ) lDelay / 1000 );
               hb_gtBeginWrite();
            }
         }
         while( --nLen );
         hb_gtSetPos( iRow, iNewCol );
         hb_gtEndWrite();
      }
   }
   hb_strfree( hText );

   hb_retc_null();
}
