HB_FUNC( SETFCLIPDATA ) // ( hWnd, cTextData, cGtfData, cRtfData ) --> lSuccessfully
{
   #ifdef _WIN64
      HWND hWnd  = ( HWND ) hb_parnll( 1 );
   #else   
      HWND hWnd  = ( HWND ) hb_parnl( 1 );
   #endif

   BOOL bGtfData  = ( hb_pcount() > 2 );
   BOOL bRtfData  = ( hb_pcount() > 3 );

   WORD     wLen;
   UINT     uFormat;
   HGLOBAL  hMem;
   void far * pMem;

   BOOL bRet;

   if ( OpenClipboard( hWnd ) )
   {
      EmptyClipboard();

      // Set Text format

      wLen = ( WORD ) hb_parclen( 2 );
      hMem = GlobalAlloc( GHND, wLen + 1 );
      if( !hMem )
      {
         hb_retl( 0 );
         return;
      }

      pMem = GlobalLock( hMem );
      memcpy( ( char * ) pMem, hb_parc( 2 ), wLen );
      GlobalUnlock( hMem );
      bRet = ( SetClipboardData( CF_TEXT, hMem ) != 0 );

      // Set GTF format

      if ( bGtfData && bRet )
      {
         uFormat = RegisterClipboardFormat( GTF );

         wLen = ( WORD ) hb_parclen( 3 );
         hMem = GlobalAlloc( GHND, wLen + 1 );
         if( !hMem )
         {
            hb_retl( 0 );
            return;
         }

         pMem = GlobalLock( hMem );
         memcpy( ( char * ) pMem, hb_parc( 3 ), wLen );
         GlobalUnlock( hMem );
         bRet = ( SetClipboardData( uFormat, hMem ) != 0 );
      }

      // Set RTF format

      if ( bRtfData && bRet )
      {
         uFormat = RegisterClipboardFormat( RTF );

         wLen = ( WORD ) hb_parclen( 4 );
         hMem = GlobalAlloc( GHND, wLen + 1 );
         if( !hMem )
         {
            hb_retl( 0 );
            return;
         }

         pMem = GlobalLock( hMem );
         memcpy( ( char * ) pMem, hb_parc( 4 ), wLen );
         GlobalUnlock( hMem );
         bRet = ( SetClipboardData( uFormat, hMem ) != 0 );
      }

      CloseClipboard();

      hb_retl( bRet );

   }
}
