#include "FiveWin.ch"

function Main()
   local oT := TTransformerTL():New( 1, 16, 2, 6 )  // layers, d_model, heads, vocab
   local aIds     := { 1, 2, 3, 4, 5, 6, 1 }
   local aTargets := { 2, 3, 4, 5, 6, 1, 2 }
   local e, nLoss

   for e := 1 to 300
      nLoss := oT:TrainStep( aIds, aTargets, 0.05 ) // cross-entropy + SGD
   next
   ? "final loss:", nLoss

   ? hb_ValToExp( oT:Generate( { 1, 2, 3 }, 4 ) )   // greedy continuation
return nil

PROCEDURE Main()
   LOCAL cNombre := Space(30)
   LOCAL nEdad := 0
   LOCAL dFecha := Date()
   LOCAL lActivo := .T.

   CLS
   setcolor("15/1, 15/4")

   @2, 2 say "Nombre:"  GET cNombre
   @4, 2 say "Edad:"    GET nEdad
   @6, 2 say "Fecha:"   GET dFecha
   @8, 2 say "Activo:"  GET lActivo

   READ

   CLS
   @0, 0 say "Datos ingresados:"
   @2, 0 say "Nombre: " + cNombre
   @3, 0 say "Edad: " + Str(nEdad)
   @4, 0 say "Fecha: " + DToC(dFecha)
   @5, 0 say "Activo: " + IF(lActivo, "Si", "No")
   INKEY(0)
   RETURN

