   // Navegar registros
   dbGoTop()
   WHILE !Eof()
      ? FieldGet(1), FieldGet(2), FieldGet(3), FieldGet(4)
      dbSkip()
   ENDDO

   // Browse interactivo
   dbGoTop()
   BROWSE()

   USE
   RETURN

// Compilar con información de debug
// hbmk2 mi_programa.prg -b

PROCEDURE Main()
   LOCAL nValor := 10
   LOCAL aDatos := { 1, 2, 3 }

   ? "Inicio del programa"

   // Punto de interrupción: agregar línea con BREAK
   BREAK

   nValor := nValor * 2
   ? "Valor:", nValor

   // Depurar valor de variable
   ? HB_ValToExp( nValor )

   // Depurar arreglo
   ? HB_ValToExp( aDatos )

   RETURN

PROCEDURE Main()

   // Usar RUN para comando simple
   RUN ls -la

   // Usar __Run() para más control
   __Run("echo Hola desde Harbour")

   //管道 (pipeline)
   RUN ls -1 | grep ".prg"

   // Ejecutar con argumentos
   RUN cp archivo1.txt archivo2.txt

   // Verificar directorio actual
   ? "Directorio:", CurDir()

   RETURN

PROCEDURE Main()
   CLS

   // Imprimir en posición específica: @fila, columna SAY
   @0, 0 say "Fila 0, Columna 0"
   @4, 9 say "Hello World!"
   @10, 20 say "Centrado en pantalla"

   // Usar row() y col() para posición actual
   @15, 0 say "Inicio"
   @row(), col() + 5 say "despues de 5 espacios"

   // Colores con setcolor
   setcolor("15/1")  // Blanco sobre azul
   @20, 0 say "Texto en color"

   setcolor("0/15")  // Negro sobre blanco brillante
   @22, 0 say "Texto invertido"

   RETURN

PROCEDURE Main()

   // Sistema operativo
   ? "OS:", OS()
   ? "Versión Harbour:", Version()

   // Variables de entorno
   ? "HOME:", GetEnv( "HOME" )
   ? "PATH:", hb_GetEnv( "PATH", "/usr/bin" )

   // Directorio actual
   ? "Directorio:", CurDir()

   // Cambiar directorio
   DirChange( "/tmp" )
   ? "Nuevo directorio:", CurDir()

   // Crear directorio
   MakeDir( "mi_carpeta" )

   // Espacio en disco
   ? "Espacio libre:", DiskSpace()

   // Ejecutar comando externo
   __Run( "ls -la" )

   // Nueva línea según SO
   ? "Salto:", hb_eol()

   // Modo de video (consola)
   SetMode( 25, 80 )

   RETURN

#include "set.ch"

PROCEDURE Main()
   LOCAL cOld, cFmt

   // Guardar y cambiar formato de fecha
   cOld := Set( _SET_DATEFORMAT, "yyyy-mm-dd" )
   ? "Fecha:", DToC( Date() )

   // Restaurar
   Set( _SET_DATEFORMAT, cOld )

   // Configurar decimales
   cOld := Set( _SET_DECIMALS, 4 )
   ? 3.14159
   Set( _SET_DECIMALS, cOld )

   // Exactitud en comparaciones
   cOld := Set( _SET_EXACT, .T. )
   ? "test" == "test"    // siempre .T.
   Set( _SET_EXACT, cOld )

   // Búsqueda suave
   cOld := Set( _SET_SOFTSEEK, .T. )

   // Eliminados
   cOld := Set( _SET_DELETED, .T. )

   // Epoch para fechas cortas
   cOld := Set( _SET_EPOCH, 1950 )

   // Ruta por defecto
   cOld := Set( _SET_DEFAULT, ".\data" )
   Set( _SET_DEFAULT, cOld )

   // Código de página
   cOld := Set( _SET_CODEPAGE, "EN" )

   // Fixed decimals
   cOld := Set( _SET_FIXED, .T. )

   RETURN

PROCEDURE Main()
   LOCAL cResultado

   // Entero con padding
   cResultado := hb_StrFormat( "Código: %05d", 42 )
   ? cResultado    // "Código: 00042"

   // Float con decimales
   cResultado := hb_StrFormat( "Precio: $%.2f", 1234.5 )
   ? cResultado    // "Precio: $1234.50"

   // Hexadecimal
   cResultado := hb_StrFormat( "Color: #%02X%02X%02X", 255, 128, 0 )
   ? cResultado    // "Color: #FF8000"

   // String con ancho fijo
   cResultado := hb_StrFormat( "|%-10s|", "Hola" )
   ? cResultado    // "|Hola      |"

   // Combinación
   cResultado := hb_StrFormat( "Fecha: %s, Cant: %d, Total: $%.2f", ;
      DToC( Date() ), 5, 99.99 )
   ? cResultado

   // Con eol
   cResultado := hb_StrFormat( "Línea 1%eLínea 2" )
   ? cResultado

   RETURN

