STATIC FUNCTION int_to_string(nValue)
     LOCAL cRetVal
     LOCAL aArray1 := {;
          "one"        ,;
          "two"        ,;
          "three"      ,;
          "four"       ,;
          "five"       ,;
          "six"        ,;
          "seven"      ,;
          "eight"      ,;
          "nine"       ,;
          "ten"        ,;
          "eleven"     ,;
          "twelve"     ,;
          "thirteen"   ,;
          "fourteen"   ,;
          "fifteen"    ,;
          "sixteen"    ,;
          "seventeen"  ,;
          "eighteen"   ,;
          "nineteen"   }

     LOCAL aArray2 := {;
          "ten"        ,;
          "twenty"     ,;
          "thirty"     ,;
          "forty"      ,;
          "fifty"      ,;
          "sixty"      ,;
          "seventy"    ,;
          "eighty"     ,;
          "ninety"     }

     IF nValue < 20
          cRetVal := aArray1[nValue]
     ELSE
          cRetVal := aArray2[Int(nValue / 10)]
          nValue -= 10 * Int(nValue / 10)
          IF Int(nValue) >= 1
               cRetVal += " " + aArray1[Int(nValue)]
          ENDIF
     ENDIF

     RETURN cRetVal

