CLASS TComm

        DATA nDevice, nInQueue, nOutQueue, nId, nStop, nBaud, nData, nErr
        DATA cParity, cStyle, cChar
        DATA aStatus

        METHOD Break() BLOCK { |Self| IIF( SetCommBreak( ::nId ) < 0, ;
                                        MsgInfo( "Error al bloquear el puerto de comuúnicaciones" ), ) }

  METHOD Close() BLOCK { |Self| IIF( CloseComm( ::nId ) < 0, ;
                                        MsgInfo( "Error intentando cerrar el puerto de comuúnicaciones" ), ) }

  METHOD Error()

  METHOD Escape( nCode ) BLOCK { |Self,nCode| IIF( EscapeCommFunction( ::nId, nCode ) < 0, ;
                                        MsgInfo( OemToAnsi( "Error enviando c¢digo de escape" ) ), ) }

  METHOD Flush( nQueue ) BLOCK { |Self,nQueue| IIF( FlushComm( ::nId, nQueue ) != 0, ;
                                        MsgInfo( "Error al vaciar el buffer de las comuúnicaciones" ), ) }

  METHOD New( nDevice, nInQueue, nOutQueue, cStyle, nBaud, cParity, nStop, nData ) CONSTRUCTOR

  METHOD SetUp()

  METHOD UnBreak() BLOCK { |Self| IIF( ClearCommBreak( ::nId ) < 0, ;
                                        MsgInfo( "Error desbloqueando el puerto de comuúnicaciones" ), ) }

  METHOD Write( cString )

ENDCLASS

