HB_FUNC( ATCBRWPOSRECT ) // ( hWnd, nRow, nCol, nWidth, hFont )
{
   #ifdef _WIN64
      HWND hWnd        = ( HWND ) hb_parnll( 1 );
      HFONT hFont      = ( HFONT ) hb_parnll( 5 );
   #else
      HWND hWnd        = ( HWND ) hb_parnl( 1 );
      HFONT hFont      = ( HFONT ) hb_parnl( 5 );
   #endif

   WORD wRow        = ( WORD ) hb_parni( 2 );
   WORD wCol        = ( WORD ) hb_parni( 3 );
   WORD wWidth      = ( WORD ) hb_parni( 4 );
   HDC hDC          = GetDC( hWnd );
   HFONT hOldFont = 0;
   WORD wMaxRight;
   TEXTMETRIC tm;
   RECT rct;

   if( hFont )
      hOldFont = ( HFONT ) SelectObject( hDC, hFont );

   GetWindowRect( hWnd, &rct );
   wMaxRight = ( WORD ) rct.right;

   GetTextMetrics( hDC, &tm );

   tm.tmHeight++;

   /* Calculate number of lines available to this Client Rect. */
   // LineCount = ( ( ( rct.bottom - rct.top ) -
   //              GetSystemMetrics( SM_CYHSCROLL ) ) / tm.tmHeight ) - 1 ;

   /* Add the extra space that will be left over on the bottom of the screen
      to the header. */
   // HeaderHeight = ( ( rct.bottom - rct.top ) -
   //                 GetSystemMetrics( SM_CYHSCROLL ) -
   //                 ( LineCount * tm.tmHeight ) ) ;

   // rct.top    += HeaderHeight + ( tm.tmHeight * ( wRow - 1 ) ) ;
   rct.top    += ( tm.tmHeight * wRow ) + 1;
   rct.bottom = rct.top + tm.tmHeight;
   rct.left   += wCol;
   rct.right  = rct.left + wWidth;

   if( hFont )
      SelectObject( hDC, hOldFont );

   ReleaseDC( hWnd, hDC );

   hb_reta( 4 );

   hb_storvni( rct.top,    -1, 1 );
   hb_storvni( rct.left,   -1, 2 );
   hb_storvni( rct.bottom, -1, 3 );
   hb_storvni( ( wMaxRight <= rct.right ) ? wMaxRight - 18: rct.right, -1, 4 );
}
