HB_FUNC( BLANK )
{
   PHB_ITEM pItem = hb_param( 1, HB_IT_ANY );
   HB_BOOL bRef = HB_ISBYREF( 1 );
   HB_BOOL bRet = ! ct_getref();

   if( ! pItem )
   {
      if( bRet )
         hb_retl( HB_FALSE );
   }
   else if( HB_IS_TIMESTAMP( pItem ) )
   {
      if( bRef )
         hb_stortdt( 0, 0, 1 );
      if( bRet )
         hb_rettdt( 0, 0 );
   }
   else if( HB_IS_DATE( pItem ) )
   {
      if( bRef )
         hb_stordl( 0, 1 );
      if( bRet )
         hb_retdl( 0 );
   }
   else if( HB_IS_NUMBER( pItem ) )
   {
      if( bRef )
         hb_stornl( 0, 1 );
      if( bRet )
         hb_retnl( 0 );
   }
   else if( HB_IS_STRING( pItem ) )
   {
      PHB_ITEM pMode = hb_param( 2, HB_IT_LOGICAL );

      if( pMode && hb_itemGetL( pMode ) )
      {
         HB_SIZE nLen = hb_itemGetCLen( pItem );
         char * szResult = ( char * ) hb_xgrab( nLen + 1 );

         if( nLen > 0 )
            hb_xmemset( szResult, ' ', nLen );
         if( bRef )
            hb_storclen( szResult, nLen, 1 );
         if( bRet )
            hb_retclen_buffer( szResult, nLen );
         else
            hb_xfree( szResult );
      }
      else
      {
         if( bRef )
            hb_storc( NULL, 1 );
         if( bRet )
            hb_retc_null();
      }
   }
   else if( HB_IS_ARRAY( pItem ) )
   {
      if( bRef )
         hb_arraySize( pItem, 0 );
      if( bRet )
         hb_reta( 0 );
   }
   else if( HB_IS_LOGICAL( pItem ) )
   {
      if( bRef )
         hb_storl( HB_FALSE, 1 );
      if( bRet )
         hb_retl( HB_FALSE );
   }
   else
   {
      if( bRet )
         hb_retl( HB_FALSE );
   }
   if( ! bRet )
      hb_ret();
