{
   LPSTR szText = ( char * ) hb_parc( 1 );

   while( * szText )
   {
      if( ( * szText ) >= 'A' && ( * szText ) <= 'Z' )
         ( * szText ) += ( 'a' - 'A' );

      szText++;
   }
   szText = ( char * ) hb_parc( 1 );

   if( szText[ 1 ] > '9' )
      szText[ 1 ] -= 'a' - 'A';

   hb_retc( ( char * ) hb_parc( 1 ) );
}
