HB_FUNC( CSTRWORD )   // cString, @nOffset, cSeparators
{
   char * pString = ( char * ) hb_parc( 1 );
	 int  iStart    = hb_parni( 2 );
	 int  iEnd      = iStart;
	 char bChar;
   char * pSeparators = ( char * ) hb_parc( 3 );

	 while( ( ( bChar = * ( pString + iEnd ) ) != 0 ) && bChar == ' ' )
	    iEnd++;

	 if( iEnd != iStart )
	 {	   
      hb_retclen( ( char * ) pString + iStart, iEnd - iStart );
	    hb_storni( iEnd, 2 );
	    return;
	 } 

   while( ( ( bChar = * ( pString + iEnd++ ) ) != 0 ) && ! bStrAt( bChar, pSeparators ) );

   if( bStrAt( bChar, pSeparators ) && ( iEnd - iStart > 1 ) )
      iEnd--;

   hb_retclen( ( char * ) pString + iStart, iEnd - iStart - ( bChar == 0 ) );
	 hb_storni( iEnd, 2 );
}
#pragma ENDDUMP

