   pBTree = hb_BTreeNew( "test_3.out", 2048, 90, HB_BTREE_UNIQUE, 0 );
   if ( pBTree != NULL )
   {
/*
      a := hb_BTreeInfo( pBTree );
      display( "File", a[ hb_BTreeINFO_FILENAME ], HB_FALSE );
      display( "Page", a[ hb_BTreeINFO_PAGESIZE ], HB_FALSE );
