void PCodeAnalizer( const HB_BYTE * pCode )
{
   while( * pCode != HB_P_ENDPROC )
   {
      switch( * pCode )
      {
         case HB_P_STATICS:   
              OutputDebugString( "HB_P_STATICS\n" );
              OutputDebugString( BToStr( HB_PCODE_MKUSHORT( &pCode[ 3 ] ) ) );
              OutputDebugString( "\n" );
              pCode += 5;
              break;

         case HB_P_SFRAME:     
              OutputDebugString( "HB_P_SFRAME \n" );
              pCode += 3;
              break;

         case HB_P_PUSHSTRSHORT:     
              OutputDebugString( "HB_P_PUSHSTRSHORT \n" );
              pCode += 2 + pCode[ 1 ];
              break;

         case HB_P_ARRAYGEN:    
              OutputDebugString( "HB_P_ARRAYGEN \n" );
              pCode += 3;
              break; 

         case HB_P_POPSTATIC:     
              OutputDebugString( "HB_P_POPSTATIC \n" );
              pCode += 3;
              break;

         case HB_P_PUSHBYTE: 
              OutputDebugString( "HB_P_PUSHBYTE \n" );
              pCode += 2;
              break;    

         case HB_P_TRUE:     
              OutputDebugString( "HB_P_TRUE \n" );
              pCode++;
              break;    

         case HB_P_FALSE:     
              OutputDebugString( "HB_P_FALSE \n" );
              pCode++;
              break;    

         case HB_P_ZERO:     
              OutputDebugString( "HB_P_ZERO \n" );
              pCode++;
              break;    

         case HB_P_PUSHNIL:     
              OutputDebugString( "HB_P_PUSHNIL \n" );
              pCode++;
              break;    

         case HB_P_ONE:     
              OutputDebugString( "HB_P_ONE \n" );
              pCode++;
              break;    

         case HB_P_PUSHBLOCK: 
              {    
                 HB_SIZE nSize = HB_PCODE_MKUSHORT( &pCode[ 1 ] );
                 OutputDebugString( "HB_P_PUSHBLOCK \n" );
                 pCode += nSize;
                 break;
              }   

         case HB_P_PUSHINT:     
              OutputDebugString( "HB_P_PUSHINT \n" );
              pCode += 3;
              break;    

         case HB_P_HASHGEN:     
              OutputDebugString( "HB_P_HASHGEN \n" );
              pCode += 3;
              break;   

         case HB_P_PUSHFUNCSYM:      
              OutputDebugString( "HB_P_PUSHFUNCSYM \n" );
              pCode += 3;
              break;   

         case HB_P_PUSHSYMNEAR: 
              OutputDebugString( "HB_P_PUSHSYMNEAR \n" );
              pCode += 2;
              break;   

         case HB_P_DOSHORT:     
              OutputDebugString( "HB_P_DOSHORT \n" );
              pCode += 2;
              break;   

         case HB_P_POPMEMVAR:     
              OutputDebugString( "HB_P_POPMEMVAR \n" );
              pCode += 3;
              break;   

         case HB_P_LINE:     
              OutputDebugString( "HB_P_LINE \n" );
              pCode += 3;
              break;   

         case HB_P_FUNCTIONSHORT:     
              OutputDebugString( "HB_P_FUNCTIONSHORT \n" );
              pCode += 2;
              break;   

         case HB_P_RETVALUE:     
              OutputDebugString( "HB_RETVALUE \n" );
              pCode++;
              break;   

         case HB_P_PUSHSTATIC:     
              OutputDebugString( "HB_P_PUSHSTATIC \n" );
              pCode += 3;
              break;   

         case HB_P_JUMPFALSENEAR:     
              OutputDebugString( "HB_P_JUMPFALSENEAR \n" );
              // if( ! hb_vmPopLogical() )
                 pCode += ( signed char ) pCode[ 1 ];
              // else
              //   pCode += 2;
              break;

         case HB_P_NOTEQUAL:     
              OutputDebugString( "HB_P_NOTEQUAL\n" );
              pCode++;
              break;   

         default:     
              OutputDebugString( BToStr( * pCode ) );
              OutputDebugString( "\n" );
              break;
      }
   }

   OutputDebugString( "HB_P_ENDPROC \n" );
}                                       

