HB_FUNC( FATTRIB )  // cFileName [,nNewAttrs] --> nAttrs
{
   LPSTR szFileName = ( char * ) hb_parc( 1 );
   WORD  wAttrs = IF( hb_pcount() > 1, ( WORD ) hb_parni( 2 ), 0 );

   // 00h        Normal
   // 01h        Read-only
   // 02h        Hidden
   // 04h        System
   // 20h        Archive

   #ifndef __FLAT__

   asm push ds;

   if( hb_pcount() > 1 )
   {
      _AH = 0x43;
      _AL = 1;
      _CX = wAttrs;
      _DS = FP_SEG( szFileName );
      _DX = FP_OFF( szFileName );
      Dos3Call();
   }
   else
   {
      _AH = 0x43;
      _AL = 0;
      _DS = FP_SEG( szFileName );
      _DX = FP_OFF( szFileName );
      Dos3Call();
   }

   asm pop ds;

   hb_retni( _CX );

   #else
      if( hb_pcount() > 1 )
         hb_retni( SetFileAttributes( szFileName, wAttrs ) ); // --> 0/1 .F./.T.
      else
         hb_retni( GetFileAttributes( szFileName ) );
   #endif
}
