HB_FUNC( HB_ASCIIUPPER )
{
   PHB_ITEM pText = hb_param( 1, HB_IT_STRING );

   if( pText )
   {
      const char * pszText = hb_itemGetCPtr( pText );
      HB_SIZE nLen = hb_itemGetCLen( pText ), u;

      for( u = 0; u < nLen; u++ )
      {
         if( HB_ISLOWER( pszText[ u ] ) )
         {
