HB_FUNC( HB_SSL_READ_LINE )
{
   if( hb_SSL_is( 1 ) )
   {
      SSL * ssl = hb_SSL_par( 1 );

      if( ssl )
      {
         int iMax        = hb_parnidef( 3, INT_MAX );
         int iTimeout    = hb_parnidef( 4, -1 );
         int iBufferSize = hb_parnidef( 5, 80 );

         int    iPos       = 0;
         int    iAllocated = 0;
         char * retval     = NULL;

         for(;; )
         {
            char buffer[ 1 ];
            int  iLen;
            int  sd = SSL_get_rfd( ssl );

            if( SSL_pending( ssl ) ||
                ( sd >= 0 && hb_socketSelectRead( ( HB_SOCKET ) sd, iTimeout ) ) )
            {
               iLen = SSL_read( ssl, buffer, 1 );

               if( iLen == SSL_ERROR_WANT_READ )
                  continue;
            }
            else
               break;

            if( iLen <= 0 )
            {
               if( retval )
                  hb_xfree( retval );

               hb_storc( NULL, 2 );
               hb_retni( iLen );
               return;
            }
            else if( buffer[ 0 ] == '\r' )
               continue;
            else if( buffer[ 0 ] == '\n' )
               break;

            if( iPos == iAllocated )
            {
               iAllocated += iBufferSize;
               retval      = ( char * ) hb_xrealloc( retval, iAllocated );
            }

            retval[ iPos++ ] = buffer[ 0 ];

            if( iPos == iMax )
               break;
         }

         if( retval )
         {
            if( ! hb_storclen_buffer( retval, iPos, 2 ) )
               hb_xfree( retval );
         }
         else
            hb_storc( NULL, 2 );

         hb_retni( iPos );
      }
   }
   else
      hb_errRT_BASE( EG_ARG, 2010, NULL, HB_ERR_FUNCNAME, HB_ERR_ARGS_BASEPARAMS );
}
