HB_FUNC( METERPAINT )         //  hWnd, hDC, nActual, nTotal, porcentage, Texto, lporcentage, 4 colores, font
{
   #ifdef _WIN64
      HWND hWnd = ( HWND ) hb_parnll( 1 );
      HDC  hDC  = ( HDC ) hb_parnll( 2 );
      HFONT hFont = ( HFONT ) hb_parnll( 12 );
   #else   
      HWND hWnd = ( HWND ) hb_parnl( 1 );
      HDC  hDC  = ( HDC ) hb_parnl( 2 );
      HFONT hFont = ( HFONT ) hb_parnl( 12 );
   #endif
   RECT rc, rcClient;
   WORD wCol, wRow, wRight;
   WORD wPercent = ( WORD ) hb_parni(  5 );
   char * cText  = ( char * ) hb_parc( 6 );
   int iPorcent  = hb_parl(   7 );
   DWORD dwPane  = hb_parnl(  8 );
   DWORD dwText  = hb_parnl(  9 );
   DWORD dwBar   = hb_parnl( 10 );
   DWORD dwBText = hb_parnl( 11 );
   HFONT hOldFont = 0;
   int nLenght  = 0;
   SIZE nSizes;

   cChars[ 0 ] = 0;

   if( hFont )
      hOldFont = ( HFONT ) SelectObject( hDC, hFont );

   if( cText[ 0 ] )
   {
      lstrcpy( ( char * ) cChars, cText );
      nLenght = lstrlen( ( char * ) cChars );
      cChars[ nLenght++ ] = ' ';

   }
   if( iPorcent )
   {
      if( wPercent == 100 )
      {
          cChars[ nLenght     ] = '1';
          cChars[ nLenght + 1 ] = '0';
      }
      else
      {
          cChars[ nLenght     ] = ' ';
          cChars[ nLenght + 1 ] = ( wPercent < 10 ? ' ' : ( BYTE ) ( wPercent / 10 )   + '0' );
      }
      cChars[ nLenght + 2 ] = ( BYTE ) ( wPercent % 10 )   + '0';
      cChars[ nLenght + 3 ] = '%';
      nLenght += 4;
   }

   GetClientRect( hWnd, &rc );

   rcClient.top    = rc.top;
   rcClient.left   = rc.left;
   rcClient.bottom = rc.bottom - 1;
   rcClient.right  = rc.right  - 1;

   GetTextExtentPoint( hDC, ( char * ) cChars, nLenght, &nSizes );

   wCol   = ( WORD ) ( ( ( rc.right - rc.left ) / 2 ) - ( nSizes.cx / 2 ) );
   wRow   = ( WORD ) ( ( ( rc.bottom - rc.top ) / 2 ) - ( nSizes.cy / 2 ) );
   wRight = ( WORD ) rc.right;
   rc.top++;
   rc.left++;
   rc.bottom--;
   rc.right = ( WORD ) --rc.right * wPercent / 100;

   SetBkColor( hDC, dwBar );
   SetTextColor( hDC, dwBText );

   ExtTextOut( hDC, wCol, wRow, ETO_CLIPPED | ETO_OPAQUE, &rc, ( char * ) cChars, nLenght, 0 );

   WindowBoxIn( hDC, &rcClient );

   SetBkColor( hDC, dwPane );
   SetTextColor( hDC, dwText );

   rc.left  = rc.right + 1;
   rc.right = wRight - 1;

   if( wPercent < 100 )
       ExtTextOut( hDC, wCol, wRow, ETO_CLIPPED | ETO_OPAQUE, &rc, ( char * ) cChars, nLenght, 0 );

   if( hFont )
      SelectObject( hDC, hOldFont );

   hb_retni( 0 );
}
#pragma ENDDUMP

