HB_FUNC( SX_DBSKIPPER )
{
   long  nSkipped   = 0;
   long  nRecs      = hb_parnl( 1 );

   if( ! ( sx_Eof() && sx_Bof() ) )
   {
      if( nRecs == 0 )
         sx_Skip( 0 );
      else if( ( nRecs > 0 ) && ! sx_Eof() )
      {
         nSkipped = 0;
         while( nSkipped < nRecs )
         {
            sx_Skip( 1 );
            if( sx_Eof() )
            {
               sx_Skip( -1 );
               nRecs = nSkipped;
            }
            else
            {
               nSkipped++;
            }
         }
      }
      else if( nRecs < 0 )
      {
         while( nSkipped > nRecs )
         {
            sx_Skip( -1 );
            if( sx_Bof() )
            {
               nRecs = nSkipped;
            }
            else
            {
               nSkipped--;
            }
         }
      }
   }

   hb_retnl( nSkipped );
}
#pragma ENDDUMP

