HB_FUNC( SX_SLIMFAST )
{
   const char * szExp = hb_parc( 1 );

   if( szExp && *szExp )
   {
      char * szDst, cQuote = 0, c;
      HB_SIZE nDst;

      szDst = hb_cdpnDupUpper( hb_vmCDP(), szExp, NULL );
      szExp = szDst;
      nDst = 0;

      while( ( c = *szExp++ ) != 0 )
      {
         if( c == cQuote )
            cQuote = 0;
         else if( ! cQuote )
         {
            if( c == '"' || c == '\'' )
               cQuote = c;
            else if( c == ' ' && nDst && szDst[ nDst - 1 ] == ' ' )
               continue;
         }
         szDst[ nDst++ ] = c;
      }

      hb_retclen_buffer( szDst, nDst );
   }
   else
      hb_retc_null();
}
