HB_FUNC( WIDTHFLINE ) // ( hDC, aText, aFonts, nLen, lTrim ) --> nWidth
{
   #ifdef __XPP__
      #define hb_parnl( x ) PARNL( x, params )
   #endif

   #ifndef _WIN64
      HDC  hDC     = ( HDC ) hb_parnl( 1 );
   #else
      HDC  hDC     = ( HDC ) hb_parnll( 1 );
   #endif

   WORD wIndex  = 1;
   WORD wArray  = ( WORD ) hb_parinfa( 2, 0 );

   LPSTR  szText;
   WORD   wText;
   HFONT  hFont;

   BOOL bLen   = ( hb_pcount() > 3 && HB_ISNUM(4) );
   WORD wLen   = ( bLen ) ? ( WORD ) hb_parni( 4 ) : 0;

   BOOL bTrim  = ( hb_pcount() > 4 ) ? hb_parl( 5 ) : FALSE;

   WORD  wStrlen = 0;
   WORD  wSize   = 0;

   TEXTMETRIC tm;

   hOldFont = 0;

   while( wIndex <= wArray )
   {
      szText = ( LPSTR ) hb_parvc( 2, wIndex );
      wText  = ( WORD ) strlen( szText );
      #ifdef __XPP__
         #define hb_parnl( x, y ) PARNL( x, params, y )
      #endif

      #ifndef _WIN64 
         hFont  = ( HFONT ) hb_parvnl( 3, wIndex );
      #else
         hFont  = ( HFONT ) hb_parvnll( 3, wIndex );
      #endif

      if ( !bLen )
         if ( bTrim && wIndex == wArray && *( szText + wText - 1 ) == ' ' )
            --wText;

      if ( bLen )
         if ( wStrlen + wText > wLen )
         {
            wText = wLen - wStrlen;
            if ( bTrim && *( szText + wText - 1) == ' ' )
               --wText;
            wArray  = 0;
         }

      SelectObject( hDC, hFont );
      wSize += LOWORD( GetTextExtent( hDC, szText, wText ) );

      GetTextMetrics( hDC, &tm );

      if ( hFont == hOldFont )
         wSize -= ( WORD ) tm.tmOverhang;

      hOldFont = hFont;

      wStrlen += wText;

      ++wIndex;
   }

   hb_retni( wSize );
}
#pragma ENDDUMP

