#include "hbclass.ch"

PROCEDURE Main()
   LOCAL hHash
   LOCAL aKeys
   LOCAL uValue

   // Crear hash vacía
   hHash := HB_Hash()

   // Crear hash con valores iniciales
   hHash := HB_Hash( "nombre", "Juan", "edad", 30 )

   // Agregar elementos
   hHash[ "email" ] := "juan@test.com"

   // Acceder a elementos
   ? hHash[ "nombre" ]
   ? hHash[ "edad" ]

   // Verificar si existe una clave
   IF HB_HHasKey( hHash, "email" )
      ? "Email:", hHash[ "email" ]
   ENDIF

   // Obtener todas las claves
   aKeys := HB_HKeys( hHash )
   ? "Claves:", HB_ArrayToCSV( aKeys )

   // Obtener todos los valores
   ? "Valores:", HB_ArrayToCSV( HB_HValues( hHash ) )

   // Eliminar un elemento
   HB_HDel( hHash, "email" )

   // Tamaño de la hash
   ? "Elementos:", HB_HLength( hHash )

   RETURN

