function Main()
   local aIds := { 3, 1, 4, 1, 5 }
   local nSeq := Len( aIds )

   local tX    := FWT_OneHot( aIds, 10 )            // [seq, vocab] booleano
   local tMask := FWT_CausalMask( nSeq )            // 0 bajo diagonal, -1e9 encima
   local tPos  := FWT_SinPos( nSeq, 16 )            // posicional sinusoidal

   ? hb_ValToExp( FWT_Shape( tX ) )                 // {5, 10}
   ? FWT_Get( tMask, 2 )                            // -1000000000 (enmascarado)
   ? FWT_Get( tPos, 1 )                             // sin(0) = 0
return nil

