function Main()
   local oTL := TTensorLogic():New()
   local hUser

   oTL:Param( "W", { { 0.3, -0.2 }, { 0.1, 0.4 } } )
   oTL:Eq( "Y[i] = sigmoid( W[i,j] * X[j] )" )

   // ... training loop here ...

   // checkpoint: every Param() tensor as raw float32 + a user hash
   oTL:SaveParams( "model.chk", { "epoch" => 100, "note" => "best val" } )

   // later / another session:
   hUser := oTL:LoadParams( "model.chk" )
   if hUser != nil
      ? "restored, epoch:", hUser[ "epoch" ]
   endif
return nil

