HB_FUNC( CCCON_READKEY )
{
   int ch = read_one_byte();
   int result = -99;

   if( ch == -1 )
   {
      hb_retni( 0 );
      return;
   }

   if( ch == 3 )
      result = -8;          /* Ctrl+C */
   else if( ch == 5 )
      result = -14;         /* Ctrl+E */
   else if( ch == 13 || ch == 10 )
      result = -1;          /* Enter */
   else if( ch == 127 )
      result = -2;          /* Backspace */
   else if( ch == 9 )
      result = -12;         /* Tab */
   else if( ch == 27 )
   {
      int next = read_one_byte();
      if( next == 91 || next == 79 )
      {
         int third = read_one_byte();
         if( next == 91 )
         {
            switch( third )
            {
               case 65: result = -9;  break;  /* Up */
               case 66: result = -10; break;  /* Down */
               case 67: result = -4;  break;  /* Right */
               case 68: result = -3;  break;  /* Left */
               case 72: result = -5;  break;  /* Home */
               case 70: result = -6;  break;  /* End */
               case 51:
               {
                  int fourth = read_one_byte();
                  if( fourth == 126 )
                     result = -7;     /* Delete */
                  break;
               }
               case 90: result = -12; break;  /* Shift+Tab */
               default: break;
            }
         }
         else if( next == 79 )
         {
            switch( third )
            {
               case 72: result = -5;  break;  /* Home */
               case 70: result = -6;  break;  /* End */
               default: break;
            }
         }
      }
   }
   else if( ch >= 32 )
      result = ch;

   hb_retni( result );
}
#pragma ENDDUMP

