   PHB_ITEM pItem = hb_param( 1, HB_IT_ANY );

   if( pItem )
   {
      if( HB_IS_STRING( pItem ) )
      {
         HB_SIZE nLen = hb_itemGetCLen( pItem );

         if( nLen > 0 )
         {
            const char * szSrc = hb_itemGetCPtr( pItem );
            char * szBuffer = ( char * ) hb_xgrab( nLen + 1 );
            HB_SIZE nPos;

            for( nPos = 0; nPos < nLen; nPos++ )
