{
   unsigned FlagCount = ( unsigned ) hb_parnidef( 1, 1 );

   if( FlagCount > 0 )
   {
      char *   FlagString;
      unsigned ByteCount = ( unsigned ) ( ( FlagCount / 8 ) + 1 );
      unsigned Byte;

      if( ! ( FlagCount % 8 ) )
         --ByteCount;
      FlagString = ( char * ) hb_xgrab( ByteCount );
      for( Byte = 0; Byte < ByteCount; Byte++ )
