         pTerm1           = hb_param( 3, HB_IT_STRING );
         Term             = ( const char ** ) hb_xgrab( sizeof( char * ) );
         pnTermSizes      = ( HB_ISIZ * ) hb_xgrab( sizeof( HB_ISIZ ) );
         Term[ 0 ]        = hb_itemGetCPtr( pTerm1 );
         pnTermSizes[ 0 ] = hb_itemGetCLen( pTerm1 );
         nTerms           = 1;
