      nSize = READING_BLOCK;

   pBuffer = hb_fsReadLine( hFileHandle, &nSize, Term, pnTermSizes, nTerms, &bFound, &bEOF );

   if( ! hb_storclen_buffer( pBuffer, nSize, 2 ) )
