HB_FUNC( HB_MATRIXMULTIPLY )
{
   PHB_ITEM pMatrix1 = hb_param( 1, HB_IT_ARRAY );
   PHB_ITEM pMatrix2 = hb_param( 2, HB_IT_ARRAY );
   HB_SIZE rows1, i, k, cols1, rows2, cols2, j;
   PHB_ITEM pRow1, pResult, pRowResult, pRowA;
   double sum, a, b;

   if( !pMatrix1 || !pMatrix2 )
   {
      hb_errRT_BASE( EG_ARG, 3012, "Invalid parameters: NIL matrix passed.", HB_ERR_FUNCNAME, HB_ERR_ARGS_BASEPARAMS );
      return;
   }

   rows1 = hb_arrayLen( pMatrix1 );
   pRow1 = ( rows1 > 0 ) ? hb_arrayGetItemPtr( pMatrix1, 1 ) : NULL;
   if( rows1 == 0 || !pRow1 || !HB_IS_ARRAY( pRow1 ) )
   {
      hb_errRT_BASE( EG_ARG, 3012, "First matrix is empty or invalid.", HB_ERR_FUNCNAME, HB_ERR_ARGS_BASEPARAMS );
      return;
   }
   cols1 = hb_arrayLen( pRow1 );

   rows2 = hb_arrayLen( pMatrix2 );
   if( rows2 == 0 )
   {
      hb_errRT_BASE( EG_ARG, 3012, "Second matrix is empty.", HB_ERR_FUNCNAME, HB_ERR_ARGS_BASEPARAMS );
      return;
   }
   cols2 = hb_arrayLen( hb_arrayGetItemPtr( pMatrix2, 1 ) );

   if( cols1 != rows2 )
   {
      hb_errRT_BASE( EG_ARG, 3012, "Matrix dimensions do not match for multiplication.", HB_ERR_FUNCNAME, HB_ERR_ARGS_BASEPARAMS );
      return;
   }

   pResult = hb_itemArrayNew( rows1 );
   for( i = 0; i < rows1; i++ )
   {
      pRowResult = hb_itemArrayNew( cols2 );
      for( j = 0; j < cols2; j++ )
      {
         sum = 0.0;
         pRowA = hb_arrayGetItemPtr( pMatrix1, i + 1 );
         for( k = 0; k < cols1; k++ )
         {
            a = hb_arrayGetND( pRowA, k + 1 );
            b = hb_arrayGetND( hb_arrayGetItemPtr( pMatrix2, k + 1 ), j + 1 );
            sum += a * b;
         }
         hb_arraySetND( pRowResult, j + 1, sum );
      }
      hb_arraySet( pResult, i + 1, pRowResult );
      hb_itemRelease( pRowResult );
   }
   hb_itemReturnRelease( pResult );
}
