HB_FUNC( LENFLINE ) // ( hDC, aText, aFonts, nWidth, lRound ) --> nLen
{
   #ifndef _WIN64
      HDC  hDC     = ( HDC ) hb_parnl( 1 );
   #else
      HDC  hDC     = ( HDC ) hb_parnll( 1 );
   #endif

   WORD wIndex  = 1;
   WORD wArray  = ( WORD ) hb_parinfa( 2, 0 );

   LPSTR  szText;
   WORD   wText, wTextOld;
   HFONT  hFont;

   BOOL bWidth  = ( hb_pcount() > 3 && HB_ISNUM(4) );
   WORD wWidth  = ( bWidth ) ? ( WORD ) hb_parni( 4 ) : 0;

   BOOL bRound  = ( hb_pcount() > 4 && HB_ISLOG(5) ) ? hb_parl( 5 ) : FALSE;

   WORD  wStrlen = 0;
   WORD  wSize   = 0, wSizeOld;

   TEXTMETRIC tm;

   hOldFont = 0;

   while( wIndex <= wArray )
   {

      szText = ( LPSTR ) hb_parvc( 2, wIndex );
      wText  = ( WORD ) strlen( szText );

      #ifdef __XPP__
         #define hb_parnl( x, y ) PARNL( x, params, y )
      #endif

      #ifndef _WIN64
         hFont  = ( HFONT ) hb_parvnl( 3, wIndex );
      #else
         hFont  = ( HFONT ) hb_parvnll( 3, wIndex );
      #endif

      if ( bWidth )
         {
            SelectObject( hDC, hFont );
            wSizeOld = wSize;
            wSize += LOWORD( GetTextExtent( hDC, szText, wText ) );

            GetTextMetrics( hDC, &tm );

            if ( hFont == hOldFont )
               wSize -= ( WORD ) tm.tmOverhang;

            hOldFont = hFont;

            if ( wSize > wWidth )
            {
               wTextOld = wText;
               wSize = wSizeOld;
               while ( wSize + LOWORD( GetTextExtent( hDC, szText, --wText ) ) > wWidth );

               if ( bRound && wText != wTextOld )
                  if ( wWidth - wSize - LOWORD( GetTextExtent( hDC, szText, wText ) ) >=
                       wSize + LOWORD( GetTextExtent( hDC, szText, wText + 1 ) ) - wWidth )
                       wText++;

               wArray  = 0;
            }
         }

      wStrlen += wText;

      ++wIndex;
   }

   hb_retni( wStrlen );
}
