HB_FUNC( UNIX_DAEMON )
{
   int fd;

   switch( fork() )
   {
      case -1:
         hb_posix_save_errno();
         hb_retni( -1 );
         return;
      case 0:
         break;
      default:
         hb_vmRequestQuit();
         exit( 0 );
   }

   if( setsid() == -1 )
   {
      hb_posix_save_errno();
      hb_retni( -1 );
      return;
   }

   if( ! HB_PARLUNIX( 1 ) && chdir( "/" ) == -1 )
   {
      /* fallthrough */
   }

   if( ! HB_PARLUNIX( 2 ) && ( fd = open( "/dev/null", O_RDWR ) ) != -1 )
   {
      ( void ) dup2( fd, STDIN_FILENO );
      ( void ) dup2( fd, STDOUT_FILENO );
      ( void ) dup2( fd, STDERR_FILENO );
      if( fd > 2 )
         ( void ) close( fd );
   }

   hb_posix_set_errno( 0 );

   hb_retni( 0 );
}
