HB_FUNC( WIN_REGQUERYVALUEEX )
{
   void * hKey;
   LPCTSTR lpKey = HB_PARSTRDEF( 2, &hKey, NULL );
   DWORD dwType = 0;
   DWORD dwSize = 0;

   if( RegQueryValueEx( ( HKEY ) hb_parptr( 1 ),
                        lpKey,
                        NULL,
                        &dwType,
                        NULL,
                        &dwSize ) == ERROR_SUCCESS )
   {
      if( dwSize > 0 )
      {
         if( dwType == REG_SZ ||
             dwType == REG_EXPAND_SZ ||
             dwType == REG_MULTI_SZ )
         {
            LPBYTE lpValue = ( LPBYTE ) hb_xgrab( ( dwSize + 1 ) * sizeof( TCHAR ) );

            if( RegQueryValueEx( ( HKEY ) hb_parptr( 1 ),
                                 lpKey,
                                 NULL,
                                 &dwType,
                                 lpValue,
                                 &dwSize ) == ERROR_SUCCESS )
            {
               dwSize /= sizeof( TCHAR );

               HB_STORSTRLEN( ( LPTSTR ) lpValue, dwSize, 5 );
            }
            else
               hb_stor( 5 );

            hb_xfree( lpValue );
         }
         else /* No translation for binary data */
         {
            LPBYTE lpValue = ( LPBYTE ) hb_xgrab( dwSize + 1 );

            if( RegQueryValueEx( ( HKEY ) hb_parptr( 1 ),
                                 lpKey,
                                 NULL,
                                 &dwType,
                                 lpValue,
                                 &dwSize ) == ERROR_SUCCESS )
            {
               if( ! hb_storclen_buffer( ( char * ) lpValue, dwSize, 5 ) )
                  hb_xfree( lpValue );
            }
            else
            {
               hb_stor( 5 );
               hb_xfree( lpValue );
            }
         }
      }
      else
         hb_storc( NULL, 5 );
   }
   else
      hb_stor( 5 );

   hb_stornl( dwType, 4 );
   hb_retnl( dwSize );

   hb_strfree( hKey );
}
