      hb_gt_wvwDrawBoxRaised( usWinNum, iTop+1, iLeft+1, iBottom-2, iRight-2, FALSE );
   }
   SelectObject( pWindowData->hdc, s_sApp->solidBrush );

   switch ( hb_parni( 7 ) )
   {
      case 1:
      {
         xy.y       = iTop + iOff - 1;
         xy.x       = iLeft + ( ( iRight - iLeft + 1 ) / 2 );
