PROCEDURE Main()
   LOCAL cTexto := "  Hola Mundo  "
   LOCAL cExtraido

   // Longitud
   ? "Longitud:", Len( cTexto )

   // Mayúsculas/Minúsculas
   ? Upper( cTexto )
   ? Lower( cTexto )

   // Recortar espacios
   ? AllTrim( cTexto )
   ? LTrim( cTexto )
   ? RTrim( cTexto )

   // Extraer subcadena
   ? SubStr( cTexto, 3, 4 )

   // Buscar
   ? At( "Mundo", cTexto )
   ? Rat( "o", cTexto )

   // Reemplazar
   ? StrTran( cTexto, "Mundo", "Harbour" )

   // Formatear
   ? PadL( "123", 10, "0" )
   ? PadR( "Hola", 20, "." )

   // Convertir
   ? Str( 123.45, 10, 2 )
   ? Val( "123.45" )
   ? Chr( 65 )
   ? Asc( "A" )

   // Repetir
   ? Replicate( "-", 40 )

   // Unir/Separar
   ? HB_ArrayToCSV( { "a", "b", "c" } )
   ? HB_ATokens( "uno,dos,tres", "," )

   RETURN

