function BinToN( aBin )

   local nFor, nNumber

   nNumber := 0

   FOR nFor := 1 TO 32
      nNumber += If( aBin[ nFor ], 2 ** ( nFor - 1 ), 0 )
   NEXT

return Int( nNumber )

