function MsgRun( cCaption, cTitle, bAction, oWndParent, aColor )

   LOCAL oDlg, uReturn, lCenterMsg := .f.

   if oWndParent == nil .and. CenterMsgs( "?" )
      lCenterMsg   := .t.
      SetAsMsgBox()
   endif

   DEFAULT cCaption := "Please, wait...",;
           bAction  := { || WaitSeconds( 1 ) }

   IF cTitle == NIL
      DEFINE DIALOG oDlg ;
         FROM 0,0 TO 3, Len( cCaption ) + 4 ;
         STYLE nOr( DS_MODALFRAME, WS_POPUP )
   ELSE
      DEFINE DIALOG oDlg ;
         FROM 0,0 TO 4, Max( Len( cCaption ), Len( cTitle ) ) + 4 ;
         TITLE cTitle ;
         STYLE nOr( DS_MODALFRAME, If( lCenterMsg, nOr( WS_CAPTION, WS_POPUP ), 0 ) )

         //STYLE DS_MODALFRAME // Fixed crashing when CenterMsgs() is used http://forums.fivetechsupport.com/viewtopic.php?f=3&p=228435#p228435
   ENDIF

   if HB_ISARRAY( aColor )
      oDlg:SetColor( aColor[ 1 ], aColor[ 2 ] )
   endif

   oDlg:bStart := { || uReturn := Eval( bAction, oDlg ), oDlg:End(), SysRefresh() }
   oDlg:cMsg   := cCaption
   oDlg:lHtml  := .F.

   ACTIVATE DIALOG oDlg ON PAINT ( hDC, cPS, Self, oDlg:SayText( oDlg:cMsg ) ) ;
      ON INIT ( Self, oDlg:Center( oWndParent ) )

return uReturn

