FUNCTION CCHOOKS_IsValidEvent( cEvent )
   RETURN AScan( CCHOOKS_ValidEvents(), {| c | c == cEvent } ) > 0

// Returns the array of hook command strings registered for cEvent in
// hSet, or an empty array if the event is absent or hSet has no hooks
// key. Safe to call with arbitrary settings hashes.

FUNCTION CCHOOKS_List( hSet, cEvent )
   IF ValType( hSet ) != "H" .OR. !hb_HHasKey( hSet, "hooks" )
      RETURN {}
   ENDIF
   IF ValType( hSet[ "hooks" ] ) != "H" .OR. ;
      !hb_HHasKey( hSet[ "hooks" ], cEvent )
      RETURN {}
   ENDIF
   RETURN hSet[ "hooks" ][ cEvent ]

// Appends cCmd to hSet["hooks"][cEvent], creating intermediate keys as
// needed. Returns .T. on success, .F. if cEvent is not a valid event.
// Mutates hSet in place; caller is responsible for CCSETTINGS_Save.

FUNCTION CCPERM_Gate( bInner, hPermissions, bAsk )
   LOCAL hPerm := CCPERM_CloneModes( hPermissions )
   RETURN {| cName, cArgsJson | ;
      CCPERM_Decide( hPerm, bInner, bAsk, cName, cArgsJson ) }

// Copies the caller's permission hash so an "a" upgrade never mutates it.

FUNCTION CCTool_TodoWrite()
   RETURN { "name" => "todo_write", ;
            "description" => "Maintain a visible task list for multi-step " + ;
               "work. Call with the full list every time -- it replaces the " + ;
               "previous list. Mark each item pending, in_progress or " + ;
               "completed; keep exactly one item in_progress while working. " + ;
               "Optional 'id' lets later items list blockers in 'blocked_by'; " + ;
               "optional 'active_form' is the present-continuous label shown " + ;
               "in the rendered list while the item is in_progress. " + ;
               "Example arguments (real JSON uses double quotes): " + ;
               "{ todos: [ " + ;
               "{ id: 'build', text: 'Build the binary', " + ;
               "active_form: 'Building the binary', " + ;
               "status: 'in_progress' }, " + ;
               "{ id: 'test', text: 'Run the test suite', " + ;
               "active_form: 'Running tests', " + ;
               "status: 'pending', " + ;
               "blocked_by: ['build'] } ] }", ;
            "parameters" => { "type" => "object", ;
               "properties" => { ;
                  "todos" => { "type" => "array", ;
                     "description" => "The full task list", ;
                     "items" => { "type" => "object", ;
                        "properties" => { ;
                           "text" => { "type" => "string", ;
                              "description" => "The task description" }, ;
                           "status" => { "type" => "string", ;
                              "description" => "pending, in_progress or completed" }, ;
                           "id" => { "type" => "string", ;
                              "description" => "Optional identifier used by " + ;
                                 "blocked_by on other items" }, ;
                           "active_form" => { "type" => "string", ;
                              "description" => "Optional present-continuous " + ;
                                 "label shown while this item is in_progress " + ;
                                 "(e.g. 'Running tests')" }, ;
                           "blocked_by" => { "type" => "array", ;
                              "description" => "Optional list of ids this " + ;
                                 "item is blocked by", ;
                              "items" => { "type" => "string" } } }, ;
                        "required" => { "text", "status" } } } }, ;
               "required" => { "todos" } }, ;
            "handler" => {| hArgs | CCTool_TodoWriteRun( hArgs ) } }

FUNCTION CCTool_UseSkill()
   RETURN { "name" => "use_skill", ;
