FUNCTION CCTOOLS_Schemas( oReg )
   LOCAL aOut := {}, cKey, hTool
   FOR EACH cKey IN hb_HKeys( oReg )
      hTool := oReg[ cKey ]
      AAdd( aOut, { "type" => "function", ;
                    "function" => { "name" => hTool[ "name" ], ;
                                    "description" => hTool[ "description" ], ;
                                    "parameters" => hTool[ "parameters" ] } } )
   NEXT
   RETURN aOut

