function ChartsAndTables( cPDF )

   local oPrn, oFont, oBold
   local nPgWidth, nPgHeight
   local aCrops, cText

   aCrops   :=  { { "CROP",      "2018", "2019" } ;
                , { "MANGOES",   6000,   7000  } ;
                , { "APPLES",    3900,   4800  } ;
                , { "GRAPES",    5000,   5800  } ;
                , { "ORANGES",   3500,   5500  } ;
                }

   cText    := ReadText()

   PRINT oPrn PREVIEW FILE cPdf

#if FW_VersionNo < 20070
   if cPdf == nil .and. oPrn:lUseHaruPDF
      oPrn:bPDF   := { || ChartsAndTables( cPdfFile ) }
   endif
#endif

   DEFINE FONT oFont NAME "Courier New" SIZE 0,-11 BOLD OF oPrn
