   PAGE

   @  2, 2 PRINT TO oPrn TEXT "Some more Charts" SIZE 17,1 CM ;
      ALIGN "" FONT oBold COLOR CLR_YELLOW OUTLINE CLR_HRED SIZE 1

   @  4, 2 PRINT TO oPrn TABLE          aCrops SIZE  4, 4 CM
   @  4, 9 PRINT TO oPrn LINE     CHART aCrops SIZE 10, 5 CM
   @  9, 2 PRINT TO oPrn DOUGHNUT CHART aCrops SIZE  6, 7 CM

   @ 17, 2 PRINT TO oPrn TEXT cText SIZE 19,3 CM FONT oFont

   ENDPAGE

   ENDPRINT

   RELEASE FON oFont, oBold

