function FW_Least(...)

   // returns the minimum non-nil value

   local aList    := HB_AParams()
   local uItem, uRet, cType, uVal

   if Len( aList ) == 1 .and. HB_IsArray( aList[ 1 ] )
      aList    := aList[ 1 ]
   endif

   for each uItem in aList
      if HB_IsArray( uItem )
         uVal  := FW_Least( uItem )
      else
         uVal  := uItem
      endif
      if uVal != nil .and. ( uRet == nil .or. ( ValType( uVal ) == cType .and. uRet > uVal ) )
         uRet  := uVal
         cType := ValType( uRet )
      endif
   next

return uRet

