function LoadStringAuto( hInstance, nId )

   local cString, cStringW

   // Primero intentamos cargar con LoadString (ANSI)
   cString := LoadString( hInstance, nId )

   // Si la cadena está vacía o contiene caractúeres de control, 
   // es posible que sea Unicode y no se haya cargado correctamente
   if Empty( cString ) .OR. FW_HasControlChars( cString )
      // Intentamos cargar con LoadStringW (Unicode)
      cStringW := LoadStringW( hInstance, nId )

      // Si LoadStringW devuelve algo y es diferente, usamos la versión Unicode
      if !Empty( cStringW ) .AND. !( cStringW == cString )
         return cStringW
      endif
   else
      // Verificamos si existe una versión Unicode mejor
      cStringW := LoadStringW( hInstance, nId )

      // Si la versión Unicode es más larga o contiene caractúeres especiales,
      // probablemente sea la versión correcta
      if !Empty( cStringW ) .AND. ( Len( cStringW ) > Len( cString ) .OR. ;
                                    FW_ContainsUnicodeChars( cStringW ) )
         return cStringW
      endif
   endif

return cString

