function MsgGet( cTitle, cText, uVar, cBmpFile, cResName, lPassword, bAction )

   local oDlg, oBmp
   local oGet, uTemp := uVar
   local lOk   := .f.

   DEFAULT cText := "", lPassword := .F.

   if ValType( uVar ) == 'A' .and. ! Empty( uVar )
      return MsgGetArray( cTitle, cText, uVar )
   endif

   if CenterMsgs( "?" )
      SetAsMsgBox()
   endif

   DEFINE DIALOG oDlg FROM 10, 20 TO 18, 59.5 TITLE cTitle
   oDlg:lTruePixel := .f.

   if ! Empty( cBmpFile ) .or. ! Empty( cResName )
      if ! Empty( cBmpFile )
         @ 1, 1 BITMAP oBmp FILENAME cBmpFile SIZE 20, 20 NO BORDER OF oDlg
      endif

      if ! Empty( cResName )
         @ 1, 1 BITMAP oBmp RESOURCE cResName SIZE 20, 20 NO BORDER OF oDlg
      endif

      @ 0.5, 6 SAY cText OF oDlg SIZE 250, 10

      if ! lPassword
         if Empty( bAction )
            @ 1.6, 4 GET uTemp SIZE 120, 12 OF oDlg
         else
            @ 1.6, 4 GET oGet VAR uTemp ;
               ACTION ( Self, oGet:SetText( uTemp := Eval( bAction ) ) ) ;
               SIZE 120, 12 OF oDlg
         endif
      else
         @ 1.6, 4 GET oGet VAR uTemp SIZE 120, 12 OF oDlg PASSWORD ACTION ( Self, oGet:lShowPassword := !oGet:lShowPassword )
      endif
   else
      @ 0.5, 3.3 SAY cText OF oDlg SIZE 250, 10
      if ! lPassword
         if Empty( bAction )
            @ 1.6, 2.3 GET uTemp SIZE 120, 12 OF oDlg
         else
            @ 1.6, 2.3 GET oGet VAR uTemp ;
               ACTION ( Self, oGet:SetText( uTemp := Eval( bAction ) ) ) ;
               SIZE 120, 12 OF oDlg
         endif
      else
         @ 1.6, 2.3 GET oGet VAR uTemp SIZE 120, 12 OF oDlg PASSWORD ACTION ( Self, oGet:lShowPassword := !oGet:lShowPassword )
      endif
   endif

   @ 2.25, 7.5 - If( oBmp == nil, 2, 0 ) BUTTON FWString( "&Ok" ) ;
      OF oDlg SIZE 35, 12 ;
      ACTION ( oDlg:End(), lOk := .t. ) DEFAULT

   @ 2.25, 16.5 - If( oBmp == nil, 2, 0 ) BUTTON FWString( "&Cancel" ) ;
      OF oDlg SIZE 35, 12 ;
      ACTION ( oDlg:End(), lOk := .f. )

   ACTIVATE DIALOG oDlg CENTERED

   if lOk
      uVar := uTemp
   endif

return lOk

