STATIC FUNCTION TestToolThenAnswer()
   LOCAL nTurn := 0, lToolCalled := .F., oAgent, cAns, lOK
   // Fake LLM: 1st call -> request a tool; 2nd call (sees result) -> answer.
   oAgent := TChatAgent():New( ;
      { |cPrompt| ;
         iif( ++nTurn == 1, "TOOL count customers", ;
              "ANSWER You have " + ParseToolResult( cPrompt ) + " customers." ) }, ;
      { |cQuery| lToolCalled := .T., "42" } )           // fake DB tool

   cAns := oAgent:Ask( "how many customers do I have?" )
   lOK := lToolCalled .and. cAns == "You have 42 customers."
   TLog( "tool_then_answer", lOK, "[" + cAns + "] turns=" + LTrim(Str(nTurn)) )
RETURN NIL

