               divElement = document.querySelector('div.flex.w-full.pb-3');
               observer = new MutationObserver(() => {
                  if (!divElement.querySelector('button')) {
                     var divChats = document.querySelector( '.flex.h-max.flex-col.gap-6.pb-52' ).children;
                     var resp = divChats[ divChats.length - 1 ].innerText;
                        window.fwh_response = resp;
                        observer.disconnect();
                  }
               });
               observer.observe(divElement, { childList: true, subtree: true });
            }, 1000 );
         }, 50 );
      endtext

      oWebView:eval( strtran( cScript, "{{cMessage}}", cMessage ) )

      nWait := 0
      while nWait <= 30
         hb_idleSleep( 1.0 )
         cResponse := oWebView:eval( "window.fwh_response;" )
         if hb_isString( cResponse ) .and. len( cResponse ) > 2
            cResponse := hb_jsonDecode( cResponse )
            exit
         endif
         nWait += 1
      enddo

      if hb_isString( cResponse )
         msgInfo( cResponse , "HuggingChat response" )
      else
         msgStop( "Can't read the response", "HuggingChat" )
      endif

   endif

return nil

