HB_FUNC( CODETEXT ) // ( cText )
{
   LPSTR szText = ( char * ) hb_parc( 1 );

   char *cCode;

   BYTE bChar;
   WORD w = 0;

   cCode = ( char * ) hb_xgrab( strlen( szText ) * 4 + 2 );

   cCode[ w ] = 0 ;
   strcat( cCode, szText );

   while( * szText )
   {
      bChar = ( BYTE ) * szText;

      if ( bChar > 0x7E )
      {
         cCode[ w ] =   0x5C ;  //  "\"
         cCode[ ++w ] = 0x27 ;  //  "'"
         cCode[ ++w ] = bChars[ ( BYTE ) bChar / 16 ];
         cCode[ ++w ] = bChars[ ( BYTE ) bChar % 16 ];
         cCode[ ++w ] = 0 ;
         szText++;
         strcat( cCode, szText );
      }
      else
         switch( bChar )
         {
           case 0x5C:  // "\"
             cCode[ w ] =   0x5C ;
             cCode[ ++w ] = 0x5C ;
             cCode[ ++w ] = 0 ;
             szText++;
             strcat( cCode, szText );
             break;
           case 0x7B:  // "{"
             cCode[ w ] =   0x5C ;
             cCode[ ++w ] = 0x7B ;
             cCode[ ++w ] = 0 ;
             szText++;
             strcat( cCode, szText );
             break;

           case 0x7D:  // "}"
             cCode[ w ] =   0x5C ;
             cCode[ ++w ] = 0x7D ;
             cCode[ ++w ] = 0 ;
             szText++;
             strcat( cCode, szText );
             break;

           default :
             szText++;
             w++;
             break;
         }
   }
   cCode[ ++w ] = 0 ;

   hb_retc( cCode );
   hb_xfree( cCode );
}
