   PHB_ITEM phbpsw   = hb_param( 2, HB_IT_STRING );
   ULONG    srclen, dstlen, crc, i;
   BYTE *   srcstr, * dststr;

   if( phbpsw )
   {
      int_cryptbl( ( BYTE * ) hb_itemGetCPtr( phbpsw ), ( ULONG ) hb_itemGetCLen( phbpsw ) );
   }
   else
   {
