   HB_SIZE nPos = 0;

   if( nSubLen )
   {
      HB_SIZE nLen = hb_parclen( 2 );
      HB_ISIZ nTo = nLen - nSubLen;

      if( nTo >= 0 )
      {
         PHB_CODEPAGE cdp = hb_vmCDP();
         const char * pszSub = hb_parc( 1 );
         const char * pszText = hb_parc( 2 );
         HB_ISIZ nStart = hb_parns( 3 );
