         if( nStart <= 1 )
            nFrom = 0;
         else if( HB_CDP_ISCHARIDX( cdp ) )
            nFrom = hb_cdpTextPos( cdp, pszText, nLen, --nStart );
         else
            nFrom = --nStart;

         if( nTo >= nFrom )
         {
            if( HB_ISNUM( 4 ) )
            {
               HB_ISIZ nEnd = hb_parns( 4 ) - 1;

               if( nEnd > 0 && HB_CDP_ISCHARIDX( cdp ) )
                  nEnd = hb_cdpTextPos( cdp, pszText, nLen, nEnd );
               nEnd -= nSubLen - 1;

               if( nEnd < nTo )
                  nTo = nEnd;
