HB_FUNC( HEIGHTFLINE ) // ( hDC, aText, aFonts, nPos ) --> nHeight
#else
   HB_FUNC( HEIGHTFLIN ) // E( hDC, aText, aFonts, nPos ) --> nHeight
#endif
{
   #ifdef __XPP__
      #define hb_parnl( x ) PARNL( x, params )
   #endif

   #ifndef _WIN64
      HDC  hDC     = ( HDC ) hb_parnl( 1 );
   #else
      HDC  hDC     = ( HDC ) hb_parnll( 1 );
   #endif

   WORD wIndex  = 1;
   WORD wArray  = ( WORD ) hb_parinfa( 2, 0 );

   WORD wText;

   BOOL bPos  = ( hb_pcount() > 3 && HB_ISNUM(4) );
   WORD wPos  = ( bPos ) ? ( WORD ) hb_parni( 4 ) : 0;

   TEXTMETRIC tm;

   WORD  wStrlen = 0;
   int   wHeight = 0;

   while( wIndex <= wArray )
   {
      if ( bPos )
      {
         wText = ( WORD ) strlen( hb_parvc( 2, wIndex ) );

         if ( wStrlen + wText >= wPos )
         {
            #ifdef __XPP__
               #define hb_parnl( x, y ) PARNL( x, params, y )
            #endif

            #ifndef _WIN64
               SelectObject( hDC, ( HGDIOBJ ) hb_parvnl( 3, wIndex ) );
            #else 
               SelectObject( hDC, ( HGDIOBJ ) hb_parvnll( 3, wIndex ) );
            #endif
            GetTextMetrics( hDC, &tm );
            wHeight = tm.tmHeight;

            wArray  = 0;
         }
         else
            wStrlen += wText;
      }
      else
      {
         #ifndef _WIN64 
            SelectObject( hDC, ( HGDIOBJ ) hb_parvnl( 3, wIndex ) );
         #else 
            SelectObject( hDC, ( HGDIOBJ ) hb_parvnll( 3, wIndex ) );
         #endif
         GetTextMetrics( hDC, &tm );
         wHeight = max( wHeight, ( int ) tm.tmHeight );
      }

      ++wIndex;
   }

   hb_retni( wHeight );
}
