   if( ( sStrLen1 = hb_parclen( 1 ) ) > 0 &&
       ( sStrLen2 = hb_parclen( 2 ) ) > 0 )
   {
      /* get parameters */
      const char * pcString1 = hb_parc( 1 );
      const char * pcString2 = hb_parc( 2 );
      char * pcRet1 = NULL, * pcRet2 = NULL;
      int iChange1, iChange2;
