HB_FUNC( TIP_HTMLSPECIALCHARS )
{
   if( HB_ISCHAR( 1 ) )
   {
      HB_ISIZ nLen = hb_parclen( 1 );

      if( nLen )
      {
         const char * pszData = hb_parc( 1 );
         char *       pszRet;
         HB_ISIZ      nPos    = 0;
         HB_ISIZ      nPosRet = 0;

         while( nLen && HB_ISSPACE( pszData[ nLen - 1 ] ) )
            nLen--;

         /* Giving maximum final length possible */
         pszRet = ( char * ) hb_xgrab( nLen * 6 + 1 );

         while( nPos < nLen )
         {
            HB_BYTE cElem = ( HB_BYTE ) pszData[ nPos ];

            if( cElem == '&' )
            {
               pszRet[ nPosRet++ ] = '&';
               pszRet[ nPosRet++ ] = 'a';
               pszRet[ nPosRet++ ] = 'm';
               pszRet[ nPosRet++ ] = 'p';
               pszRet[ nPosRet++ ] = ';';
            }
            else if( cElem == '<' )
            {
               pszRet[ nPosRet++ ] = '&';
               pszRet[ nPosRet++ ] = 'l';
               pszRet[ nPosRet++ ] = 't';
               pszRet[ nPosRet++ ] = ';';
            }
            else if( cElem == '>' )
            {
               pszRet[ nPosRet++ ] = '&';
               pszRet[ nPosRet++ ] = 'g';
               pszRet[ nPosRet++ ] = 't';
               pszRet[ nPosRet++ ] = ';';
            }
            else if( cElem == '"' )
            {
               pszRet[ nPosRet++ ] = '&';
               pszRet[ nPosRet++ ] = 'q';
               pszRet[ nPosRet++ ] = 'u';
               pszRet[ nPosRet++ ] = 'o';
               pszRet[ nPosRet++ ] = 't';
               pszRet[ nPosRet++ ] = ';';
            }
            else if( cElem == '\'' )
            {
               pszRet[ nPosRet++ ] = '&';
               pszRet[ nPosRet++ ] = '#';
               pszRet[ nPosRet++ ] = '0';
               pszRet[ nPosRet++ ] = '3';
               pszRet[ nPosRet++ ] = '9';
               pszRet[ nPosRet++ ] = ';';
            }
            else if( cElem == '\r' )
            {
               pszRet[ nPosRet++ ] = '&';
               pszRet[ nPosRet++ ] = '#';
               pszRet[ nPosRet++ ] = '0';
               pszRet[ nPosRet++ ] = '1';
               pszRet[ nPosRet++ ] = '3';
               pszRet[ nPosRet++ ] = ';';
            }
            else if( cElem == '\n' )
            {
               pszRet[ nPosRet++ ] = '&';
               pszRet[ nPosRet++ ] = '#';
               pszRet[ nPosRet++ ] = '0';
               pszRet[ nPosRet++ ] = '1';
               pszRet[ nPosRet++ ] = '0';
               pszRet[ nPosRet++ ] = ';';
            }
            else if( cElem >= ' ' )
            {
               pszRet[ nPosRet++ ] = cElem;
            }

            nPos++;
         }

         hb_retclen_buffer( ( char * ) hb_xrealloc( pszRet, nPosRet + 1 ), nPosRet );
      }
      else
         hb_retc_null();
   }
   else
      hb_errRT_BASE( EG_ARG, 3012, NULL, HB_ERR_FUNCNAME, HB_ERR_ARGS_BASEPARAMS );
}
#pragma ENDDUMP

