STATIC FUNCTION BuildCompactVocab( aHFIds )
   LOCAL aLocal2HF := {}, hHF2Local := { => }, id
   for each id in aHFIds
      if !hb_HHasKey( hHF2Local, id )
         AAdd( aLocal2HF, id )
         hHF2Local[ id ] := Len( aLocal2HF )    // 1-based local id
      endif
   next
RETURN { aLocal2HF, hHF2Local }

