function FW_HasControlChars( cString )

   local nI, nChar

   for nI := 1 to Len( cString )
      nChar := Asc( SubStr( cString, nI, 1 ) )
      // Detectar caractúeres de control (excepto espacios normales)
      if ( nChar < 32 .AND. nChar != 9 .AND. nChar != 10 .AND. nChar != 13 ) .OR. ;
         ( nChar > 126 .AND. nChar < 160 )
         return .T.
      endif
   next nI

return .F.

