Function SetDbCombo(nCommodityCode,oCmbItems,aLstOfItems,aCodeOfItems,nItemCode)

    aLstOfItems:={};aCodeOfItems:={}

    IF nCommodityCode == 25 // Fruits
        aLstOfItems:={"Apple","Grapes","Mango"}
        aCodeOfItems:={21,31,41}
    ELSEIF nCommodityCode == 35// Vegetables
        aLstOfItems:={"Cucumber","Potato","Tomato"}
        aCodeOfItems:={51,61,71}
    ENDIF

    // The sequence of commads are important here. ie The default ItemCode should be assigned only 
    // after calling oCmbItems:SetItems() and then followed by a oCmbItems:refresh()
    oCmbItems:SetItems(aCodeOfItems,aLstOfItems)

    IF nCommodityCode == 25 // Fruits
        nItemCode:=41  // 3rd Item ie Mango should be the default one on DbCombo
    ELSEIF nCommodityCode == 35// Vegetables
        nItemCode:=61 // 2nd Item ie Potato should be the default one on DbCombo
    Endif
    oCmbItems:Refresh()

Return NIL


