FUNCTION Test_Http()
   LOCAL hReq, hRes, aChunks, bTransport

   hReq := { "url" => "https://x/y", "headers" => {}, "body" => "{}", "timeout" => 30 }

   // injected transport: feeds two chunks, reports HTTP 200
   aChunks := {}
   bTransport := {| hR, bOnChunk | ;
      HB_SYMBOL_UNUSED( hR ), ;
      Eval( bOnChunk, "data: a" + Chr(10) ), ;
      Eval( bOnChunk, "data: b" + Chr(10) ), ;
      { "ok" => .T., "status" => 200, "curl_code" => 0, "error" => "" } }
   hRes := CCHTTP_Post( hReq, {| c | AAdd( aChunks, c ) }, bTransport )
   T_Equal( hRes[ "ok" ], .T., "http: transport ok" )
   T_Equal( hRes[ "status" ], 200, "http: status passthrough" )
   T_Equal( Len( aChunks ), 2, "http: chunk count" )
   T_Equal( aChunks[ 1 ], "data: a" + Chr(10), "http: first chunk" )

   // injected transport reporting a network failure
   bTransport := {| hR, bOnChunk | ;
      HB_SYMBOL_UNUSED( hR ), HB_SYMBOL_UNUSED( bOnChunk ), ;
      { "ok" => .F., "status" => 0, "curl_code" => 7, "error" => "couldnt connect" } }
   hRes := CCHTTP_Post( hReq, {| c | HB_SYMBOL_UNUSED( c ) }, bTransport )
   T_Equal( hRes[ "ok" ], .F., "http: failure ok flag" )
   T_Equal( hRes[ "curl_code" ], 7, "http: curl code passthrough" )

   // --- CCHTTP_Fetch ---

   // per-request transport override returns its result verbatim
   hRes := CCHTTP_Fetch( { "url" => "https://x/y", "transport" => ;
      {| hR | HB_SYMBOL_UNUSED( hR ), ;
              { "ok" => .T., "status" => 200, "body" => "hello", "error" => "" } } } )
   T_Equal( hRes[ "ok" ], .T., "fetch: transport ok" )
   T_Equal( hRes[ "status" ], 200, "fetch: transport status" )
   T_Equal( hRes[ "body" ], "hello", "fetch: transport body" )

   // the module-level test transport is used when no per-request one is set
   CCHTTP_SetTestTransport( {| hR | ;
      { "ok" => .T., "status" => 201, "body" => "M:" + hR[ "method" ], "error" => "" } } )
   hRes := CCHTTP_Fetch( { "url" => "https://x", "method" => "POST" } )
   T_Equal( hRes[ "status" ], 201, "fetch: module transport status" )
   T_Equal( hRes[ "body" ], "M:POST", "fetch: method passthrough" )
   CCHTTP_SetTestTransport( NIL )

   // missing url -> structured error, no crash
   hRes := CCHTTP_Fetch( {=>} )
   T_Equal( hRes[ "ok" ], .F., "fetch: missing url ok flag" )
   T_Equal( hRes[ "error" ], "missing url", "fetch: missing url error" )

   // url with an embedded quote is rejected before reaching the command line
   hRes := CCHTTP_Fetch( { "url" => 'https://x/' + Chr( 34 ) + ' bad' } )
   T_Equal( hRes[ "ok" ], .F., "fetch: unsafe url ok flag" )
   T_Equal( hRes[ "error" ], "invalid url", "fetch: unsafe url error" )

   RETURN NIL

FUNCTION Test_Perm()
   LOCAL bGate, bInner, hPerm, nInner, nAsk

   // allow -> inner runs
   nInner := 0
   bInner := {| cN, cA | HB_SYMBOL_UNUSED( cN ), HB_SYMBOL_UNUSED( cA ), ;
                         nInner++, "ran" }
   bGate := CCPERM_Gate( bInner, { "read" => "allow" }, NIL )
   T_Equal( Eval( bGate, "read", "{}" ), "ran", "perm: allow runs inner" )
   T_Equal( nInner, 1, "perm: allow called inner once" )

   // deny -> inner never runs
   nInner := 0
   bGate := CCPERM_Gate( bInner, { "shell" => "deny" }, NIL )
   T_Assert( "denied by policy" $ Eval( bGate, "shell", "{}" ), ;
             "perm: deny returns policy error" )
   T_Equal( nInner, 0, "perm: deny did not call inner" )

   // ask + "y" -> inner runs
   nInner := 0
   bGate := CCPERM_Gate( bInner, { "shell" => "ask" }, ;
      {| cN, cA | HB_SYMBOL_UNUSED( cN ), HB_SYMBOL_UNUSED( cA ), "y" } )
   T_Equal( Eval( bGate, "shell", "{}" ), "ran", "perm: ask+y runs inner" )

   // ask + "n" -> denied
   nInner := 0
   bGate := CCPERM_Gate( bInner, { "shell" => "ask" }, ;
      {| cN, cA | HB_SYMBOL_UNUSED( cN ), HB_SYMBOL_UNUSED( cA ), "n" } )
   T_Assert( "denied by user" $ Eval( bGate, "shell", "{}" ), ;
             "perm: ask+n returns user error" )
   T_Equal( nInner, 0, "perm: ask+n did not call inner" )

   // ask + "a" -> session upgrade: inner runs twice, ask asked once
   nInner := 0
   nAsk := 0
   bGate := CCPERM_Gate( bInner, { "shell" => "ask" }, ;
      {| cN, cA | HB_SYMBOL_UNUSED( cN ), HB_SYMBOL_UNUSED( cA ), nAsk++, "a" } )
   Eval( bGate, "shell", "{}" )
   Eval( bGate, "shell", "{}" )
   T_Equal( nAsk, 1, "perm: 'a' asks only once" )
   T_Equal( nInner, 2, "perm: 'a' runs inner both times" )

   // ask with no bAsk -> fails closed (deny)
   nInner := 0
   bGate := CCPERM_Gate( bInner, { "shell" => "ask" }, NIL )
   T_Assert( "denied" $ Eval( bGate, "shell", "{}" ), "perm: ask + no bAsk denies" )
   T_Equal( nInner, 0, "perm: ask + no bAsk did not call inner" )

   // invalid mode -> treated as ask (here, no bAsk -> deny)
   bGate := CCPERM_Gate( bInner, { "shell" => "maybe" }, NIL )
   T_Assert( "denied" $ Eval( bGate, "shell", "{}" ), "perm: invalid mode treated as ask" )

   // caller's permissions hash is not mutated by an "a" upgrade
   hPerm := { "shell" => "ask" }
   bGate := CCPERM_Gate( bInner, hPerm, ;
      {| cN, cA | HB_SYMBOL_UNUSED( cN ), HB_SYMBOL_UNUSED( cA ), "a" } )
   Eval( bGate, "shell", "{}" )
   T_Equal( hPerm[ "shell" ], "ask", "perm: caller hash not mutated" )
   RETURN NIL

FUNCTION Test_Todo()
   LOCAL aNorm, aList

   // --- CCTODO_Norm ---
   aNorm := CCTODO_Norm( { { "text" => "a", "status" => "bogus" } } )
   T_Equal( aNorm[ 1 ][ "status" ], "pending", "todo: bad status -> pending" )

   aNorm := CCTODO_Norm( { { "text" => "a", "status" => "in_progress" } } )
   T_Equal( aNorm[ 1 ][ "status" ], "in_progress", "todo: valid status kept" )

   aNorm := CCTODO_Norm( { "not a hash", { "text" => "ok", "status" => "pending" } } )
   T_Equal( Len( aNorm ), 1, "todo: non-hash element dropped" )

   aNorm := CCTODO_Norm( { { "status" => "pending" } } )
   T_Equal( Len( aNorm ), 0, "todo: element missing text dropped" )

   aNorm := CCTODO_Norm( "not an array" )
   T_Equal( Len( aNorm ), 0, "todo: non-array input -> empty list" )

   // --- CCTODO_Set / CCTODO_Get round-trip ---
   CCTODO_Set( { { "text" => "first", "status" => "pending" }, ;
                 { "text" => "second", "status" => "completed" } } )
   aList := CCTODO_Get()
   T_Equal( Len( aList ), 2, "todo: set/get round-trips the list" )
   T_Equal( aList[ 1 ][ "text" ], "first", "todo: get keeps item text" )

   // --- CCTODO_HasOpen ---
   CCTODO_Set( { { "text" => "a", "status" => "pending" } } )
   T_Equal( CCTODO_HasOpen(), .T., "todo: pending item -> has open" )

   CCTODO_Set( { { "text" => "a", "status" => "in_progress" } } )
   T_Equal( CCTODO_HasOpen(), .T., "todo: in_progress item -> has open" )

   CCTODO_Set( { { "text" => "a", "status" => "completed" }, ;
                 { "text" => "b", "status" => "completed" } } )
   T_Equal( CCTODO_HasOpen(), .F., "todo: all completed -> no open" )

   CCTODO_Set( {} )
   T_Equal( CCTODO_HasOpen(), .F., "todo: empty list -> no open" )

   // --- new fields: id, active_form, blocked_by ---
   aNorm := CCTODO_Norm( { { "text" => "a", "status" => "in_progress", ;
                             "id" => "t1", ;
                             "active_form" => "Working on a", ;
                             "blocked_by" => { "t0", "x" } } } )
   T_Equal( aNorm[ 1 ][ "id" ], "t1", "todo: id preserved" )
   T_Equal( aNorm[ 1 ][ "active_form" ], "Working on a", ;
            "todo: active_form preserved" )
   T_Equal( Len( aNorm[ 1 ][ "blocked_by" ] ), 2, ;
            "todo: blocked_by preserved" )

   aNorm := CCTODO_Norm( { { "text" => "a", "status" => "pending" } } )
   T_Equal( aNorm[ 1 ][ "id" ], "", "todo: missing id defaults to empty" )
   T_Equal( aNorm[ 1 ][ "active_form" ], "", ;
            "todo: missing active_form defaults to empty" )
   T_Equal( Len( aNorm[ 1 ][ "blocked_by" ] ), 0, ;
            "todo: missing blocked_by defaults to empty array" )

   // --- CCTODO_IsBlocked ---
   aList := CCTODO_Norm( { ;
      { "text" => "build", "status" => "pending", "id" => "build" }, ;
      { "text" => "test",  "status" => "pending", "id" => "test", ;
        "blocked_by" => { "build" } } } )
   T_Equal( CCTODO_IsBlocked( aList[ 2 ], aList ), .T., ;
            "todo: depends on pending blocker -> blocked" )
   aList[ 1 ][ "status" ] := "completed"
   T_Equal( CCTODO_IsBlocked( aList[ 2 ], aList ), .F., ;
            "todo: depends on completed blocker -> not blocked" )

   T_Equal( CCTODO_IsBlocked( ;
      { "text" => "x", "status" => "pending" }, aList ), .F., ;
      "todo: missing blocked_by key -> not blocked" )

   RETURN NIL

static function TestDBF( oDb )

   // Create DBF
   if ! File( oDb:cDatabase )
      dbCreate( oDb:cDatabase, { ;
         { "ID",    "N", 5, 0 }, ;
         { "LABEL", "C", 20, 0 }, ;
         { "VALUE", "N", 10, 2 } } )
   endif

   if ! oDb:Open()
      ? "  Error: " + oDb:LastError()
      return nil
   endif

   ? "  Connected: " + oDb:cDriver + " (" + oDb:cDatabase + ")"

   // Append records
   oDb:Append(); oDb:FieldPut(1, 1); oDb:FieldPut(2, "Alpha"); oDb:FieldPut(3, 10.5)
   oDb:Append(); oDb:FieldPut(1, 2); oDb:FieldPut(2, "Beta");  oDb:FieldPut(3, 20.3)
   oDb:Append(); oDb:FieldPut(1, 3); oDb:FieldPut(2, "Gamma"); oDb:FieldPut(3, 30.7)

   ? "  Records: " + LTrim(Str(oDb:RecCount()))

   oDb:GoTop()
   while ! oDb:Eof()
      ? "    " + LTrim(Str(oDb:FieldGet(1))) + " " + AllTrim(oDb:FieldGet(2)) + " " + LTrim(Str(oDb:FieldGet(3)))
      oDb:Skip()
   enddo

   oDb:Close()
   ? "  Closed"

return nil

