FUNCTION Main(

   local oWnd
   local oBtn

   DEFINE WINDOW oWnd TITLE "FWH Remote View - main" ;
      FROM 3, 3 TO 24, 70

   @ 1, 2 BUTTON oBtn PROMPT "Abrir di&alogo hijo" ;
      OF oWnd SIZE 140, 30 ;
      ACTION ChildDialog()

   ACTIVATE WINDOW oWnd ;
      ON INIT ( RemoteViewSetOffset( 200, 200 ), ;
