function Main(
   local oWnd, oRich, oBtnBlue, oBtnRed, oBtnBlack, oBtnBold, oBtnItalic
   local cText := "Select any phrase in this text." + CRLF + ;
                  "Then click Blue or Red button." + CRLF + ;
                  "The selected text will change color." + CRLF + ;
                  "Other formatting (bold, italic, size) stays."

   LoadLibrary( "riched20.dll" )

   DEFINE WINDOW oWnd TITLE "TRichEdit SetSelColor Test" ;
      FROM 0, 0 TO 520, 700 PIXEL

   @ MARGIN, MARGIN RICHEDIT oRich VAR cText SIZE 680, 420 PIXEL OF oWnd

   @ BTN_Y, 10 BUTTON oBtnBlue PROMPT "Blue" SIZE 80, BTN_H PIXEL OF oWnd ;
      ACTION oRich:SetTextColor( CLR_BLUE )

   @ BTN_Y, 100 BUTTON oBtnRed PROMPT "Red" SIZE 80, BTN_H PIXEL OF oWnd ;
      ACTION oRich:SetTextColor( CLR_RED )

   @ BTN_Y, 190 BUTTON oBtnBlack PROMPT "Black" SIZE 80, BTN_H PIXEL OF oWnd ;
      ACTION oRich:SetTextColor( CLR_BLACK )

