// Storing a PullDown menu into a DBF

#include "FiveWin.ch"

extern MsgAbout          // declare extern the actions used inside the DBF
extern MsgInfo           // declare extern the actions used inside the DBF

static oWnd

//----------------------------------------------------------------------------//

function Main()

   SET _3DLOOK ON

   DEFINE WINDOW oWnd TITLE "Storing Menus at DBFs" ;
      MENU BuildMenu() MDI

   SET MESSAGE OF oWnd TO "Storing menus at a DBF"

   ACTIVATE WINDOW oWnd

return nil

//----------------------------------------------------------------------------//

function BuildMenu()

   local oMenu
   local cAction

   USE Menu

   MENU oMenu

      while ! Eof()
         do case
            case Menu->Type == 0
                 MENU

            case Menu->Type == 1
                 if ! Empty( cAction := Menu->Action )
                    if Menu->nVirtKey == 0
                       MENUITEM   ( AllTrim( Menu->Text ) ) ;
                          BLOCK  &( cAction ) ;
                          MESSAGE ( AllTrim( Menu->Msg ) )
                    else
                       MENUITEM   ( AllTrim( Menu->Text ) ) ;
                          BLOCK  &( cAction ) ;
                          MESSAGE ( AllTrim( Menu->Msg ) ) ;
                          ACCELERATOR Menu->nState, Menu->nVirtKey
                    endif
                 else
                    MENUITEM ( AllTrim( Menu->Text ) ) ;
                       MESSAGE ( AllTrim( Menu->Msg ) )
                 endif

            case Menu->Type == 2
                 SEPARATOR

            case Menu->Type == 3
                 ENDMENU
         SKIP
      end

   ENDMENU

   USE

return oMenu

//----------------------------------------------------------------------------//

function AppExit()

   oWnd:End()

return nil

//----------------------------------------------------------------------------//

