#include "FiveWin.ch"
#include "SmartBtn.ch"

function Main()

   local oDlg
   local aBtn := Array( 4, 4 )

   DEFINE DIALOG oDlg ;
      SIZE 790, 470 PIXEL TRUEPIXEL ;
      TITLE "I 4 TIPI DI PULSANTE"
     //COLOR CLR_WHITE, RGB( 10, 22, 34 )

   @ 20, 280 SAY "THE 4 TYPES OF SMARTBUTTON" OF oDlg ;
      SIZE 260, 24 PIXEL   TRANSPARENT


   @ 60, 195 SAY "NORMAL"       OF oDlg  PIXEL TRANSPARENT
   @ 60, 345 SAY "HOVER"        OF oDlg  PIXEL TRANSPARENT
   @ 60, 500 SAY "PRESSED"      OF oDlg  PIXEL TRANSPARENT
   @ 60, 650 SAY "DISABLED"     OF oDlg  PIXEL TRANSPARENT

DrawRow( oDlg,  90, "RECTANGULAR", "Straight edges",       BTN_RECT,   aBtn[ 1 ], "Save", "save.png" )
DrawRow( oDlg, 170, "ROUNDED",  "Rounded corners", BTN_ROUND,  aBtn[ 2 ], "Save", "save.png" )
DrawRow( oDlg, 250, "PILL",      "Capsule",            BTN_PILL,   aBtn[ 3 ], "Save", "save.png" )
DrawRow( oDlg, 330, "CIRCULAR",    "Circle",            BTN_CIRCLE, aBtn[ 4 ], "Save", "save.png" )

ACTIVATE DIALOG oDlg CENTERED ;
      ON INIT SetStates( aBtn )

return nil




 static function DrawRow( oDlg, nTop, cTitle, cSub, nShape, aBtns, cPrompt, cImage)

   local aAjuste := { LEFT, RIGHT, TOP, BOTTOM }
   local nW, nH, nPadding, nAjuste
   local nPos:= 1

   if nShape == BTN_CIRCLE
      nW       := 60
      nH       := 60
      nPadding := 0
   else
      nW       := 130
      nH       := 38
      nPadding := 22

     if nShape == BTN_RECT .OR. nShape == BTN_PILL .OR. nShape == BTN_ROUND
            nPos:= 1
         Endif

   @ nTop, 25 SAY cTitle OF oDlg ;
      SIZE 120, 18 PIXEL    TRANSPARENT


   @ nTop + 22, 25 SAY cSub OF oDlg ;
      SIZE 120, 18 PIXEL     TRANSPARENT

   @ nTop, 165 SMARTBTN aBtns[ 1 ] PROMPT cPrompt ;
   OF oDlg SIZE nW, nH PIXEL ;
   BORDER ;
   PADDING nPadding ;
   AJUSTE aAjuste[ nPos ] ;
   IMAGE cImage ;
   SHAPE nShape ;
   ACTION MsgInfo( "Normal" )

@ nTop, 315 SMARTBTN aBtns[ 2 ] PROMPT cPrompt ;
   OF oDlg SIZE nW, nH PIXEL ;
   BORDER ;
   PADDING nPadding ;
   AJUSTE aAjuste[ nPos ] ;
   IMAGE cImage ;
   SHAPE nShape ;
   ACTION MsgInfo( "Hover" )

@ nTop, 465 SMARTBTN aBtns[ 3 ] PROMPT cPrompt ;
   OF oDlg SIZE nW, nH PIXEL ;
   BORDER ;
   PADDING nPadding ;
   AJUSTE aAjuste[ nPos ] ;
   IMAGE cImage ;
   SHAPE nShape ;
   ACTION MsgInfo( "Pressed" )

@ nTop, 615 SMARTBTN aBtns[ 4 ] PROMPT cPrompt ;
   OF oDlg SIZE nW, nH PIXEL ;
   BORDER ;
   PADDING nPadding ;
   AJUSTE aAjuste[ nPos ] ;
   IMAGE cImage ;
   SHAPE nShape ;
   ACTION MsgInfo( "Disabled" )

for n= 1 to 4
    aBtns[ n ]:SetColor( CLR_WHITE,  )
  next

return nil


static function SetStates( aBtn )

   local n

   for n := 1 to 4
      aBtn[ n, 2 ]:lMOver   := .T.
      aBtn[ n, 3 ]:lPressed := .T.
      aBtn[ n, 4 ]:lChecked := .T.
      aBtn[ n, 4 ]:lDisabled := .T.

      aBtn[ n, 1 ]:Refresh()
      aBtn[ n, 2 ]:Refresh()
      aBtn[ n, 3 ]:Refresh()
      aBtn[ n, 4 ]:Refresh()
   next

return nil

